/**
 * Vibe Transfer 方案管理服务
 * 负责 vibe 方案的增删改查，存取全局变量；编码存酒馆服务器（图片仍在 IndexedDB）
 */

import { VIBE_STORAGE_KEY } from '../constants';
import type { VibeEntry, VibeScheme, VibeStorage } from '../types';
import { deleteVibeImage, getVibeImages } from './cgCache';
import { deleteVibeEncoding, getVibeEncodings, putVibeEncoding } from './vibeEncodingStore';
import { generateId } from './id';
import { notifyErrorThrottled } from './notify';

/** 默认空存储 */
const DEFAULT_VIBE_STORAGE: VibeStorage = {
  schemes: [],
  activeSchemeId: null,
};

// ====== 存取 ======

/**
 * 把条目的大字段剥离成可持久化形态：
 * - 只有在 `encoding` 已确认落库（存在 `encodingKey`）时才剥离，只留 `encodingKey`；
 *   否则保留 `encoding`，避免 IndexedDB 写入失败时静默丢数据；
 * - `imageBase64` 本就在 IndexedDB，直接剥离。
 * 全局变量里因此只保留轻量元数据。
 */
function toPersistedVibe(v: VibeEntry): VibeEntry {
  const { encoding, imageBase64, ...rest } = v;
  const persisted: VibeEntry = { ...rest };
  if (v.encodingKey) {
    persisted.encodingKey = v.encodingKey;
  } else if (encoding) {
    // 尚未确认落库：保留 encoding，等迁移/导入确认后再剥离
    persisted.encoding = encoding;
  }
  return persisted;
}

/**
 * 旧数据迁移：把全局变量里遗留的 encoding 搬到服务器。
 * 先 await 写入成功、再设置 encodingKey 并保存（此时才会剥离 encoding）；
 * 因此失败时原数据仍留在全局变量里，下次加载可重试（幂等）。
 */
async function migrateLegacyEncodings(storage: VibeStorage): Promise<void> {
  let migrated = false;
  for (const scheme of storage.schemes) {
    for (const vibe of scheme.vibes) {
      if (!vibe.encoding || vibe.encodingKey) continue;
      const key = generateId();
      try {
        await putVibeEncoding(key, vibe.encoding);
        vibe.encodingKey = key;
        migrated = true;
      } catch (e) {
        console.warn('[vibeManager] 迁移 vibe 编码失败，保留原值待下次重试:', e);
      }
    }
  }
  if (migrated) saveVibeStorage(storage);
}

/** 从酒馆全局变量加载 Vibe 存储 */
export function loadVibeStorage(): VibeStorage {
  try {
    const saved = getVariables({ type: 'global' }) as Record<string, any>;
    const storage = saved?.[VIBE_STORAGE_KEY];
    if (storage && typeof storage === 'object' && Array.isArray(storage.schemes)) {
      // 迁移异步执行，不阻塞读取；失败会保留 encoding 以便重试
      void migrateLegacyEncodings(storage as VibeStorage);
      return storage as VibeStorage;
    }
  } catch (e) {
    console.warn('[vibeManager] 加载 Vibe 存储失败:', e);
  }
  return { ...DEFAULT_VIBE_STORAGE };
}

/** 保存 Vibe 存储到酒馆全局变量（只写轻量元数据；编码在服务器、图片在 IndexedDB） */
export function saveVibeStorage(storage: VibeStorage): void {
  try {
    const cleanStorage: VibeStorage = {
      schemes: storage.schemes.map(s => ({
        ...s,
        vibes: s.vibes.map(toPersistedVibe),
      })),
      activeSchemeId: storage.activeSchemeId,
    };
    const current = (getVariables({ type: 'global' }) as Record<string, any>) || {};
    current[VIBE_STORAGE_KEY] = cleanStorage;
    replaceVariables(current, { type: 'global' });
  } catch (e) {
    console.error('[vibeManager] 保存 Vibe 存储失败:', e);
    notifyErrorThrottled('Vibe 方案写入酒馆变量失败，刷新后可能丢失');
  }
}

// ====== .naiv4vibebundle 解析 ======

/**
 * 解析 .naiv4vibebundle 文件内容，提取 vibe 条目
 * .naiv4vibebundle 是 NovelAI V4 的 Vibe Bundle 格式，包含多个 vibe 的编码数据
 * 注意：此格式不包含图片 base64，而是直接存储模型特征向量
 * @returns 包含 vibe 条目的数组，每个条目包含 id、name、encoding、infoExtracted、strength
 */
export function parseVibeBundle(fileContent: string): Array<{
  id: string;
  name: string;
  encoding: string;
  infoExtracted: number;
  strength: number;
}> {
  try {
    const data = JSON.parse(fileContent);
    if (data.identifier !== 'novelai-vibe-transfer-bundle') {
      throw new Error('不是有效的 NovelAI Vibe Bundle 文件');
    }
    if (!Array.isArray(data.vibes)) {
      throw new Error('Vibe Bundle 格式错误：缺少 vibes 数组');
    }

    return data.vibes.map((vibe: any) => {
      // 提取 v4-5full 模型的编码数据
      const encoding = vibe.encodings?.['v4-5full']?.unknown?.encoding;
      if (!encoding) {
        throw new Error(`Vibe ${vibe.id} 缺少编码数据`);
      }

      return {
        id: vibe.id,
        name: vibe.name || vibe.id.substring(0, 13),
        encoding,
        infoExtracted: vibe.importInfo?.information_extracted ?? 1.0,
        strength: vibe.importInfo?.strength ?? 0.6,
      };
    });
  } catch (e: any) {
    throw new Error(`解析 .naiv4vibebundle 文件失败: ${e.message}`);
  }
}

// ====== 方案管理 ======

/** 创建新方案 */
export function createScheme(name: string): VibeStorage {
  const storage = loadVibeStorage();
  const now = Date.now();
  const newScheme: VibeScheme = {
    id: generateId(),
    name,
    vibes: [],
    createdAt: now,
    updatedAt: now,
  };
  storage.schemes.push(newScheme);
  if (storage.schemes.length === 1) {
    storage.activeSchemeId = newScheme.id;
  }
  saveVibeStorage(storage);
  return storage;
}

/** 删除方案（同时清理服务器中的编码与 IndexedDB 中的图片） */
export function deleteScheme(schemeId: string): VibeStorage {
  const storage = loadVibeStorage();
  const scheme = storage.schemes.find(s => s.id === schemeId);
  if (scheme) {
    // 异步清理 IndexedDB 中的图片与编码
    scheme.vibes.forEach(v => {
      deleteVibeImage(v.id).catch(e => console.warn('[vibeManager] 清理 vibe 图片失败:', e));
      if (v.encodingKey) {
        deleteVibeEncoding(v.encodingKey).catch(e => console.warn('[vibeManager] 清理 vibe 编码失败:', e));
      }
    });
  }
  storage.schemes = storage.schemes.filter(s => s.id !== schemeId);
  if (storage.activeSchemeId === schemeId) {
    storage.activeSchemeId = storage.schemes.length > 0 ? storage.schemes[0].id : null;
  }
  saveVibeStorage(storage);
  return storage;
}

/** 重命名方案 */
export function renameScheme(schemeId: string, newName: string): VibeStorage {
  const storage = loadVibeStorage();
  const scheme = storage.schemes.find(s => s.id === schemeId);
  if (scheme) {
    scheme.name = newName;
    scheme.updatedAt = Date.now();
    saveVibeStorage(storage);
  }
  return storage;
}

/** 设置激活方案 */
export function setActiveScheme(schemeId: string | null): VibeStorage {
  const storage = loadVibeStorage();
  storage.activeSchemeId = schemeId;
  saveVibeStorage(storage);
  return storage;
}

/** 一个待写入的 vibe 条目（编码尚未落库） */
export interface VibeImportEntry {
  name: string;
  encoding: string;
  infoExtracted: number;
  strength: number;
}

/**
 * 向指定方案批量写入 vibe 条目（编码落酒馆服务器，全局变量只留元数据）。
 * 条目 id 与编码键都用 generateId() 生成——不用来源自带的 id，避免跨方案导入时键冲突。
 * 编码写入成功后才记录条目；任一步失败即回滚本次已写入项，不留指向空记录的 encodingKey。
 */
export async function importVibesToScheme(
  schemeId: string | null,
  entries: VibeImportEntry[],
): Promise<VibeStorage> {
  let storage = loadVibeStorage();
  let scheme = schemeId
    ? storage.schemes.find(s => s.id === schemeId)
    : (storage.schemes.find(s => s.id === storage.activeSchemeId) ?? storage.schemes[0]);

  // 没有任何方案时自动创建一个，支持“直接导入、自动建方案”
  if (!scheme) {
    storage = createScheme('默认 Vibe');
    scheme =
      storage.schemes.find(s => s.id === storage.activeSchemeId) ?? storage.schemes[storage.schemes.length - 1];
  }
  if (!scheme) {
    throw new Error('无法创建 Vibe 方案');
  }
  const target = scheme;
  const writtenKeys: string[] = [];
  try {
    for (const entry of entries) {
      const id = generateId();
      const encodingKey = generateId();
      // 编码写入成功后才记录条目；失败即中止，避免留下指向空记录的 encodingKey
      await putVibeEncoding(encodingKey, entry.encoding);
      writtenKeys.push(encodingKey);
      target.vibes.push({
        id,
        fileName: entry.name,
        encodingKey,
        encoding: entry.encoding, // 本会话内存可用；saveVibeStorage 会剥离
        infoExtracted: entry.infoExtracted,
        strength: entry.strength,
      });
    }
  } catch (e) {
    // 回滚本次已写入的编码，避免服务器残留
    for (const key of writtenKeys) {
      deleteVibeEncoding(key).catch(() => {});
    }
    throw e;
  }
  target.updatedAt = Date.now();
  saveVibeStorage(storage);
  return storage;
}

/** 导入 .naiv4vibebundle 到指定方案（解析后转交 importVibesToScheme） */
export async function importVibeBundleToScheme(
  schemeId: string | null,
  fileContent: string,
): Promise<VibeStorage> {
  // 先解析；文件无效时直接抛错，不产生空方案
  return importVibesToScheme(schemeId, parseVibeBundle(fileContent));
}

/** 从方案删除 vibe */
export function removeVibeFromScheme(schemeId: string, vibeId: string): VibeStorage {
  const storage = loadVibeStorage();
  const scheme = storage.schemes.find(s => s.id === schemeId);
  if (scheme) {
    const removed = scheme.vibes.find(v => v.id === vibeId);
    scheme.vibes = scheme.vibes.filter(v => v.id !== vibeId);
    scheme.updatedAt = Date.now();
    saveVibeStorage(storage);
    // 异步清理 IndexedDB 中的图片与编码
    deleteVibeImage(vibeId).catch(e => console.warn('[vibeManager] 清理 vibe 图片失败:', e));
    if (removed?.encodingKey) {
      deleteVibeEncoding(removed.encodingKey).catch(e =>
        console.warn('[vibeManager] 清理 vibe 编码失败:', e),
      );
    }
  }
  return storage;
}

/** 更新 vibe 参数 */
export function updateVibeParams(
  schemeId: string,
  vibeId: string,
  params: { infoExtracted?: number; strength?: number },
): VibeStorage {
  const storage = loadVibeStorage();
  const scheme = storage.schemes.find(s => s.id === schemeId);
  if (scheme) {
    const vibe = scheme.vibes.find(v => v.id === vibeId);
    if (vibe) {
      if (params.infoExtracted !== undefined) vibe.infoExtracted = params.infoExtracted;
      if (params.strength !== undefined) vibe.strength = params.strength;
      scheme.updatedAt = Date.now();
      saveVibeStorage(storage);
    }
  }
  return storage;
}

// ====== 获取激活方案的 vibes（从 IndexedDB 异步加载图片与编码）======

/** 获取当前激活方案的所有 vibe 条目（用于传入 generateImage） */
export function getActiveVibes(): VibeEntry[] {
  const storage = loadVibeStorage();
  if (!storage.activeSchemeId) return [];
  const scheme = storage.schemes.find(s => s.id === storage.activeSchemeId);
  return scheme?.vibes ?? [];
}

/** 获取当前激活方案的所有 vibe 条目（含图片与编码），异步从服务器 / IndexedDB 补回大字段 */
export async function getActiveVibesWithImages(): Promise<VibeEntry[]> {
  const vibes = getActiveVibes();
  if (vibes.length === 0) return [];
  // 批量读取：图片与编码各只开一次 IndexedDB 连接/事务
  const imageKeys = vibes.filter(v => !v.imageBase64).map(v => v.id);
  const encodingKeys = vibes.filter(v => !v.encoding && v.encodingKey).map(v => v.encodingKey as string);
  const [imageMap, encodingMap] = await Promise.all([
    getVibeImages(imageKeys),
    getVibeEncodings(encodingKeys),
  ]);
  return vibes.map(v => ({
    ...v,
    imageBase64: v.imageBase64 ?? imageMap.get(v.id) ?? '',
    encoding: v.encoding ?? (v.encodingKey ? encodingMap.get(v.encodingKey) : undefined),
  }));
}
