/**
 * 统一的界面提示工具。
 * 优先使用酒馆的 toastr；拿不到时退回控制台，避免使用阻塞式 alert。
 */

/** 普通错误提示 */
export function notifyError(message: string, title = '错误'): void {
  if (typeof toastr !== 'undefined') {
    toastr.error(message, title, { timeOut: 6000 });
  } else {
    console.error(`[notify] ${title}: ${message}`);
  }
}

/** 成功提示 */
export function notifySuccess(message: string, title = '完成'): void {
  if (typeof toastr !== 'undefined') {
    toastr.success(message, title, { timeOut: 3000 });
  } else {
    console.log(`[notify] ${message}`);
  }
}

/** 信息提示 */
export function notifyInfo(message: string, title = ''): void {
  if (typeof toastr !== 'undefined') {
    toastr.info(message, title, { timeOut: 3000 });
  } else {
    console.log(`[notify] ${message}`);
  }
}

let lastThrottledAt = 0;

/**
 * 限流错误提示：用于「每次按键都可能触发」的保存路径，避免刷屏。
 */
export function notifyErrorThrottled(message: string, title = '错误', minIntervalMs = 5000): void {
  const now = Date.now();
  if (now - lastThrottledAt < minIntervalMs) return;
  lastThrottledAt = now;
  notifyError(message, title);
}
