import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { parseDialogueScript } from '../parser';
import { AlertTriangle, FolderOpen, Search, Trash2, X } from './Icons';

// ====== 类型 ======

interface SaveLoadEntry {
  messageId: number;
  sceneName: string;
  speaker: string;
  preview: string;
}

interface SaveLoadScreenProps {
  onClose: () => void;
  onLoadMessage: (messageId: number) => void;
  onDeleteFromMessage: (messageId: number) => Promise<void>;
  currentMessageId: number | null;
  playSfx: () => void;
}

// ====== 常量 ======

const ITEM_HEIGHT = 72; // 每条档位的固定高度（px）
const OVERSCAN = 4; // 上下各多渲染几条，避免滚动白闪

// ====== 虚拟滚动 Hook ======

function useVirtualScroll(itemCount: number, itemHeight: number, containerRef: React.RefObject<HTMLDivElement | null>) {
  const [scrollTop, setScrollTop] = useState(0);
  const [containerHeight, setContainerHeight] = useState(0);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const observer = new ResizeObserver(entries => {
      for (const entry of entries) {
        setContainerHeight(entry.contentRect.height);
      }
    });
    observer.observe(el);
    setContainerHeight(el.clientHeight);

    return () => observer.disconnect();
  }, [containerRef]);

  const handleScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    setScrollTop(e.currentTarget.scrollTop);
  }, []);

  const totalHeight = itemCount * itemHeight;
  const startIndex = Math.max(0, Math.floor(scrollTop / itemHeight) - OVERSCAN);
  const endIndex = Math.min(itemCount - 1, Math.ceil((scrollTop + containerHeight) / itemHeight) + OVERSCAN);
  const offsetY = startIndex * itemHeight;

  return { totalHeight, startIndex, endIndex, offsetY, handleScroll };
}

// ====== 主组件 ======

export const SaveLoadScreen: React.FC<SaveLoadScreenProps> = ({
  onClose,
  onLoadMessage,
  onDeleteFromMessage,
  currentMessageId,
  playSfx,
}) => {
  useEffect(() => {
    playSfx();
  }, []);

  // ====== 数据加载 ======
  const [entries, setEntries] = useState<SaveLoadEntry[]>([]);
  const [refreshKey, setRefreshKey] = useState(0);

  const loadEntries = useCallback(() => {
    try {
      const lastId = getLastMessageId();
      const messages = getChatMessages(`0-${lastId}`, { role: 'assistant' });
      const result = messages.map(msg => {
        const parsed = parseDialogueScript(msg.message);
        const segments = parsed.segments;
        let sceneName = '';
        for (const seg of segments) {
          if (seg.effects.bg) sceneName = seg.effects.bg;
        }
        const firstSeg = segments[0];
        const speaker = firstSeg?.speaker || '—';
        const preview = firstSeg?.text || '';
        return {
          messageId: msg.message_id,
          sceneName: sceneName || '未知场景',
          speaker,
          preview: preview.length > 50 ? preview.slice(0, 50) + '…' : preview || '(空)',
        };
      });
      // 倒序：最新在上
      setEntries(result.reverse());
    } catch (e) {
      console.warn('[SaveLoadScreen] 加载楼层列表失败:', e);
      setEntries([]);
    }
  }, []);

  useEffect(() => {
    loadEntries();
  }, [loadEntries, refreshKey]);

  // ====== 范围筛选 ======
  const [rangeInput, setRangeInput] = useState('');
  const [isRangeActive, setIsRangeActive] = useState(false);

  const filteredEntries = useMemo(() => {
    if (!isRangeActive || !rangeInput.trim()) return entries;

    const match = rangeInput.trim().match(/^(\d+)\s*[-–—]\s*(\d+)$/);
    if (!match) return entries;

    const from = parseInt(match[1], 10);
    const to = parseInt(match[2], 10);
    const lo = Math.min(from, to);
    const hi = Math.max(from, to);

    return entries.filter(e => e.messageId >= lo && e.messageId <= hi);
  }, [entries, rangeInput, isRangeActive]);

  const handleRangeKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      setIsRangeActive(true);
    } else if (e.key === 'Escape') {
      setRangeInput('');
      setIsRangeActive(false);
    }
  };

  const clearRange = () => {
    setRangeInput('');
    setIsRangeActive(false);
  };

  // ====== 虚拟滚动 ======
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const { totalHeight, startIndex, endIndex, offsetY, handleScroll } = useVirtualScroll(
    filteredEntries.length,
    ITEM_HEIGHT,
    scrollContainerRef,
  );

  const visibleEntries = filteredEntries.slice(startIndex, endIndex + 1);

  // ====== 删除确认弹窗 ======
  const [deleteTarget, setDeleteTarget] = useState<SaveLoadEntry | null>(null);
  const [isDeleting, setIsDeleting] = useState(false);

  const handleDeleteClick = (e: React.MouseEvent, entry: SaveLoadEntry) => {
    e.stopPropagation();
    playSfx();
    setDeleteTarget(entry);
  };

  const handleConfirmDelete = async () => {
    if (!deleteTarget) return;
    setIsDeleting(true);
    try {
      await onDeleteFromMessage(deleteTarget.messageId);
      setDeleteTarget(null);
      // 刷新列表
      setRefreshKey(k => k + 1);
    } catch (e) {
      console.error('[SaveLoadScreen] 删除失败:', e);
    } finally {
      setIsDeleting(false);
    }
  };

  const handleCancelDelete = () => {
    playSfx();
    setDeleteTarget(null);
  };

  // 计算将被删除的楼层数
  const deleteCount = useMemo(() => {
    if (!deleteTarget) return 0;
    return entries.filter(e => e.messageId >= deleteTarget.messageId).length;
  }, [deleteTarget, entries]);

  const handleClose = () => {
    playSfx();
    onClose();
  };

  return (
    <div className="game-modal fixed inset-0 z-50 cozy-overlay flex flex-col items-center justify-center p-4 short-landscape:p-2 md:p-6 animate-in fade-in duration-200">
      <div className="max-w-4xl w-full h-[90%] short-landscape:h-[96%] md:h-[85%] flex flex-col rounded-[36px] bg-[#f7f9fa] border border-white shadow-[0_24px_64px_rgba(30,36,43,0.14)] relative overflow-hidden text-[#1e242b]">
        {/* Header - 类似图1顶部 */}
        <div className="relative z-10 flex justify-between items-center px-8 py-5 border-b border-[#edf1f4] bg-white/70 shrink-0">
          <div className="flex flex-col">
            <h2 className="font-sans-m3 text-[18px] text-[#1e242b] font-bold tracking-tight">
              存档与回溯
            </h2>
            <span className="font-mono-retro text-[9px] text-[#84919e] uppercase tracking-wider">
              SAVED NODES · {filteredEntries.length} RECORDS
            </span>
          </div>
          <button
            onClick={handleClose}
            className="w-8 h-8 flex items-center justify-center bg-[#edf1f4] hover:bg-[#dde3e8] rounded-full text-[#526070] hover:text-[#1e242b] transition-all cursor-pointer active:scale-95"
          >
            <X size={15} />
          </button>
        </div>

        {/* 范围筛选栏：像图1的搜索药丸 (Search Pill Bar) */}
        <div className="relative z-10 px-8 py-3 border-b border-[#edf1f4] bg-white/40 flex items-center gap-3">
          <div className="flex items-center gap-2.5 flex-1 px-4 py-2 rounded-full bg-white border border-[#edf1f4] shadow-[0_2px_8px_rgba(30,36,43,0.03)]">
            <Search size={15} className="text-[#84919e]" />
            <input
              type="text"
              value={rangeInput}
              onChange={e => {
                setRangeInput(e.target.value);
                if (!e.target.value.trim()) setIsRangeActive(false);
              }}
              onKeyDown={handleRangeKeyDown}
              placeholder="按楼层筛选（如 5-20），回车确定…"
              className="flex-1 bg-transparent font-sans-m3 text-[13px] text-[#1e242b] outline-none placeholder:text-[#84919e]"
            />
            {isRangeActive && (
              <button
                onClick={() => {
                  playSfx();
                  clearRange();
                }}
                className="text-[#84919e] hover:text-[#1e242b] p-1 rounded-full cursor-pointer"
              >
                <X size={13} />
              </button>
            )}
          </div>
          <span className="font-mono-retro text-[9px] text-[#84919e] uppercase tracking-wider hidden sm:inline">
            FILTER
          </span>
        </div>

        {/* Content — 虚拟滚动 */}
        <div
          ref={scrollContainerRef}
          className="flex-1 overflow-y-auto px-6 max-md:portrait:px-2 py-4 max-md:portrait:py-2 short-landscape:px-4 short-landscape:py-2 cozy-scrollbar relative z-10"
          onScroll={handleScroll}
        >
          {filteredEntries.length === 0 && (
            <div className="flex flex-col items-center justify-center h-full text-[var(--color-cozy-muted)] opacity-60">
              <span className="font-mono-retro text-sm tracking-[0.3em] mb-2">
                {isRangeActive ? 'OUT_OF_RANGE' : 'NO_ARCHIVES'}
              </span>
              <span className="font-serif-sc text-xs tracking-widest">
                {isRangeActive ? '该范围内无系统记录' : '等待剧情节点创建'}
              </span>
            </div>
          )}

          {filteredEntries.length > 0 && (
            <div style={{ height: totalHeight, position: 'relative' }}>
              <div style={{ position: 'absolute', top: offsetY, left: 0, right: 0 }}>
                {visibleEntries.map(entry => {
                  const isCurrent = entry.messageId === currentMessageId;
                  return (
                    <div key={entry.messageId} style={{ height: ITEM_HEIGHT }} className="flex items-stretch py-1.5">
                      <button
                        onClick={() => {
                          playSfx();
                          onLoadMessage(entry.messageId);
                        }}
                        className={`
                          group flex-1 min-w-0 text-left px-5 py-3.5 rounded-l-[22px] transition-all duration-200 cursor-pointer relative overflow-hidden flex items-center
                          ${isCurrent ? 'bg-[#526070] text-white shadow-sm' : 'bg-white hover:bg-white/95 text-[#1e242b] shadow-[0_2px_8px_rgba(30,36,43,0.03)]'}
                        `}
                      >
                        <div className="flex items-center gap-4 h-full relative z-10 w-full">
                          {/* 编号大字排版 */}
                          <div className="shrink-0 w-10 text-center">
                            <span
                              className={`font-mono-retro text-[13px] font-bold tracking-wider
                              ${isCurrent ? 'text-white' : 'text-[#84919e]'}`}
                            >
                              {String(entry.messageId).padStart(3, '0')}
                            </span>
                          </div>

                          <div className={`w-px h-6 ${isCurrent ? 'bg-white/30' : 'bg-[#edf1f4]'}`} />

                          {/* 内容 */}
                          <div className="flex-1 min-w-0 flex flex-col justify-center">
                            <div className="flex items-center gap-2 mb-0.5">
                              <span className={`font-serif-sc text-[14.5px] font-semibold truncate leading-tight min-w-0 ${isCurrent ? 'text-white' : 'text-[#1e242b]'}`}>
                                {entry.sceneName}
                              </span>
                              {isCurrent && (
                                <span className="font-mono-retro text-[8px] text-[#526070] bg-white tracking-wider px-1.5 py-0.2 rounded font-bold shrink-0">
                                  CURRENT
                                </span>
                              )}
                            </div>
                            <div className={`flex items-center gap-2 text-[11px] truncate ${isCurrent ? 'text-white/80' : 'text-[#747f8d]'}`}>
                              <span className="font-medium shrink-0">
                                {entry.speaker}
                              </span>
                              <span>—</span>
                              <span className="truncate">
                                {entry.preview}
                              </span>
                            </div>
                          </div>

                          <div className={`shrink-0 opacity-0 group-hover:opacity-100 transition-opacity ${isCurrent ? 'text-white' : 'text-[#526070]'}`}>
                            <FolderOpen size={16} />
                          </div>
                        </div>
                      </button>

                      {/* 唯一的删除动作按钮：极简纯净圆角按键 */}
                      <button
                        onClick={e => handleDeleteClick(e, entry)}
                        className="px-4 flex items-center justify-center bg-white hover:bg-red-50 text-[#84919e] hover:text-red-500 rounded-r-[22px] border-l border-[#edf1f4] transition-colors cursor-pointer"
                        title="删除该节点及后续"
                      >
                        <Trash2 size={15} />
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>

        {/* 底部渐变遮罩（手机横屏收窄，减少对列表内容的遮挡） */}
        <div className="absolute bottom-0 left-0 right-0 h-8 short-landscape:h-4 bg-gradient-to-t from-[rgba(245,236,228,0.95)] to-transparent pointer-events-none z-20" />
      </div>

      {/* ====== 截断删除确认弹窗 (Cozy 风格) ====== */}
      {deleteTarget && (
        <div className="absolute inset-0 z-[200] cozy-overlay flex items-center justify-center animate-in fade-in duration-200">
          <div className="cozy-surface p-8 max-w-md w-full mx-4 rounded-[24px] shadow-[0_20px_40px_rgba(109,88,76,0.15)] relative overflow-hidden border-[color:rgba(188,74,60,0.3)]">
            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-[rgba(188,74,60,0)] via-[rgba(188,74,60,0.8)] to-[rgba(188,74,60,0)]" />

            <div className="flex items-center gap-3 mb-4 text-[#a44840]">
              <AlertTriangle size={20} className="animate-pulse" />
              <h3 className="font-mono-retro text-sm tracking-[0.2em] font-bold">TRUNCATE_WARNING</h3>
            </div>

            <p className="font-serif-sc text-[var(--color-cozy-ink)] text-[15px] leading-relaxed mb-3">
              将清除自{' '}
              <span className="text-[#a44840] font-bold font-mono-retro">
                #{String(deleteTarget.messageId).padStart(3, '0')}
              </span>{' '}
              节点起的所有后续记录。
            </p>
            <p className="font-mono-retro text-[11px] text-[var(--color-cozy-muted)] tracking-wider mb-8">
              预计销毁数据区块: <span className="text-[var(--color-cozy-ink)] font-bold">{deleteCount}</span>{' '}
              个。此操作不可逆转。
            </p>

            <div className="flex gap-4 justify-end">
              <button
                onClick={handleCancelDelete}
                disabled={isDeleting}
                className="px-6 py-2 rounded-[12px] cozy-button-icon text-xs tracking-widest font-mono-retro disabled:opacity-50"
              >
                CANCEL
              </button>
              <button
                onClick={() => {
                  playSfx();
                  handleConfirmDelete();
                }}
                disabled={isDeleting}
                className="px-6 py-2 rounded-[12px] cozy-button-danger text-xs tracking-widest font-mono-retro disabled:opacity-50 relative overflow-hidden group font-bold"
              >
                <div className="absolute inset-0 bg-white/20 -translate-x-full group-hover:animate-[scan_1s_ease-out_infinite]" />
                <span className="relative z-10">{isDeleting ? 'PURGING...' : 'CONFIRM_PURGE'}</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 动画 */}
      <style>{`
        @keyframes archiveSlideIn {
          from { opacity: 0; transform: translateY(10px) scale(0.98); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
      `}</style>
    </div>
  );
};
