/**
 * Preload Service - Preload CG, Voice, Background and Character Sprite resources
 *
 * 三个阶段（resources / CG / voice）面向不同服务商，可并行执行：
 * - resources 走 CDN
 * - CG 走 Director LLM + NovelAI（严格串行）
 * - voice 走 MiniMax（队列串行）
 *
 * 并行时各阶段只更新共享 state 中属于自己的字段，再由单一 publish() 原子推送进度，
 * 避免三个阶段各自 notifyProgress 互相覆盖。
 */

import { CG_PREWARM_RANGE_COUNT, IMAGE_PRELOAD_CONCURRENCY, VOICE_PREWARM_MAX_COUNT } from '../constants';
import { buildDirectorParagraphs, parseDialogueScript } from '../parser';
import { getPreloadedImageCache, preloadImageBatch } from '../resourceLoader';
import type { DialogueSegment, ResourceConfig, VoiceConfig } from '../types';
import { getCGImage, makeRangeCacheKey } from './cgCache';
import {
  abortCGGeneration,
  getCGForRange,
  loadCGRangeRecipeBundle,
  loadCGSettings,
  triggerCGGenerationWithRange,
} from './cgTaskManager';
import {
  cancelPreloadVoice,
  isPreloadCancelled,
  resetPreloadVoice,
  setPreloadingState,
  synthesizeAndPreloadVoice,
} from './voiceService';

export interface PreloadProgress {
  phase: 'idle' | 'checking' | 'resources' | 'cg' | 'voice' | 'done' | 'error';
  /** 0-100，跨阶段加权后的总体进度（单调不回退） */
  overallPercent: number;
  cgTotal: number;
  cgCompleted: number;
  cgCached: number;
  voiceTotal: number;
  voiceCompleted: number;
  voiceCached: number;
  bgTotal: number;
  bgCompleted: number;
  bgCached: number;
  spriteTotal: number;
  spriteCompleted: number;
  spriteCached: number;
  currentTask?: string;
  error?: string;
}

type ProgressCallback = (progress: PreloadProgress) => void;

const progressListeners: Set<ProgressCallback> = new Set();

/** 当前生效的预加载 run id：cancelPreload / 新 run 会递增它，使旧 run 的回调静默失效 */
let activeRunId = 0;

function emptyProgress(overallPercent = 0): PreloadProgress {
  return {
    phase: 'idle',
    overallPercent,
    cgTotal: 0,
    cgCompleted: 0,
    cgCached: 0,
    voiceTotal: 0,
    voiceCompleted: 0,
    voiceCached: 0,
    bgTotal: 0,
    bgCompleted: 0,
    bgCached: 0,
    spriteTotal: 0,
    spriteCompleted: 0,
    spriteCached: 0,
  };
}

/** 提前结束（无段落/无楼层）时也推送终态，避免加载界面卡在 0 */
function notifySkipped(message: string): void {
  const progress = emptyProgress(100);
  progress.phase = 'done';
  progress.currentTask = message;
  notifyProgress(progress);
}

let currentProgress: PreloadProgress = emptyProgress();

function notifyProgress(progress: PreloadProgress) {
  currentProgress = progress;
  for (const listener of progressListeners) {
    try {
      listener(progress);
    } catch (e) {
      console.error('[preloadService] Progress callback error:', e);
    }
  }
}

export function onPreloadProgress(callback: ProgressCallback): () => void {
  progressListeners.add(callback);
  callback(currentProgress);
  return () => progressListeners.delete(callback);
}

export function getPreloadProgress(): PreloadProgress {
  return currentProgress;
}

/** 单次预加载的共享可变状态（各阶段只写自己的字段） */
interface RunState {
  phase: PreloadProgress['phase'];
  overallPercent: number;
  cgTotal: number;
  cgCompleted: number;
  cgCached: number;
  voiceTotal: number;
  voiceCompleted: number;
  voiceCached: number;
  bgTotal: number;
  bgCompleted: number;
  bgCached: number;
  spriteTotal: number;
  spriteCompleted: number;
  spriteCached: number;
  currentTask?: string;
  error?: string;
  resourcesDone: boolean;
  cgDone: boolean;
  voiceDone: boolean;
  cgEnabled: boolean;
  voiceEnabled: boolean;
}

/**
 * 从段落中提取所有需要的背景和立绘资源
 */
function extractResourceUrls(
  segments: DialogueSegment[],
  resourceConfig: ResourceConfig,
): {
  backgrounds: Set<string>;
  sprites: Set<string>;
} {
  const backgrounds = new Set<string>();
  const sprites = new Set<string>();

  // 解析背景图（优先 bgKey，其次 bgName）
  const resolveBg = (bgName: string, bgKey?: string): string => {
    if (bgKey && resourceConfig.backgrounds[bgKey]) return resourceConfig.backgrounds[bgKey];
    if (bgName && resourceConfig.backgrounds[bgName]) return resourceConfig.backgrounds[bgName];
    return '';
  };

  // 解析角色立绘
  const resolveChar = (charName: string, face?: string): string => {
    const charImages = resourceConfig.characters[charName];
    if (!charImages) return '';
    if (face && charImages[face]) return charImages[face];
    if (charImages['默认']) return charImages['默认'];
    if (charImages['default']) return charImages['default'];
    const keys = Object.keys(charImages);
    return keys.length > 0 ? charImages[keys[0]] : '';
  };

  // 累积状态，用于正确解析每个段落的实际资源
  let currentChar = '';
  let currentAbout = '';
  let currentFace = '';

  for (const seg of segments) {
    const eff = seg.effects;

    // 背景
    if (eff.bg) {
      const bgUrl = resolveBg(eff.bg, eff.bgKey);
      if (bgUrl) backgrounds.add(bgUrl);
    }

    // CG（也算作背景资源）
    if (eff.cg && resourceConfig.cg[eff.cg]) {
      backgrounds.add(resourceConfig.cg[eff.cg]);
    }

    // 角色立绘（累积计算）
    if (eff.char) {
      currentChar = eff.char;
      currentAbout = '';
      currentFace = '';
    }
    if (eff.about) {
      currentAbout = eff.about;
      currentFace = '';
    }
    if (eff.face) {
      currentFace = eff.face;
    }

    const spriteChar = currentAbout || currentChar;
    if (spriteChar) {
      const spriteUrl = resolveChar(spriteChar, currentFace);
      if (spriteUrl) sprites.add(spriteUrl);
    }
  }

  return { backgrounds, sprites };
}

/** 阶段 1：背景图与立绘（并发加载） */
async function preloadResourcesPhase(
  state: RunState,
  runId: number,
  segments: DialogueSegment[],
  resourceConfig: ResourceConfig,
  publish: () => void,
): Promise<void> {
  const isActive = () => runId === activeRunId;
  try {
    const { backgrounds, sprites } = extractResourceUrls(segments, resourceConfig);
    const bgArray = Array.from(backgrounds);
    const spriteArray = Array.from(sprites);

    // 复用 preloadImage 的模块级缓存（图片 URL -> 已加载图片）
    const imageCache = getPreloadedImageCache();

    state.bgTotal = bgArray.length;
    state.spriteTotal = spriteArray.length;
    state.bgCached = bgArray.filter(url => imageCache.has(url)).length;
    state.spriteCached = spriteArray.filter(url => imageCache.has(url)).length;
    state.currentTask = `正在加载背景图和立绘资源...（背景 ${state.bgCached}/${bgArray.length} 已缓存, 立绘 ${state.spriteCached}/${spriteArray.length} 已缓存）`;
    publish();

    const bgToLoad = bgArray.filter(url => !imageCache.has(url));
    state.currentTask = `正在加载背景图 ${state.bgCached}/${bgArray.length}...`;
    publish();
    await preloadImageBatch(bgToLoad, IMAGE_PRELOAD_CONCURRENCY, done => {
      if (!isActive()) return;
      state.bgCompleted = state.bgCached + done;
      state.currentTask = `正在加载背景图 ${state.bgCompleted}/${bgArray.length}...`;
      publish();
    });
    state.bgCompleted = bgArray.length;

    const spriteToLoad = spriteArray.filter(url => !imageCache.has(url));
    state.currentTask = `正在加载立绘 ${state.spriteCached}/${spriteArray.length}...`;
    publish();
    await preloadImageBatch(spriteToLoad, IMAGE_PRELOAD_CONCURRENCY, done => {
      if (!isActive()) return;
      state.spriteCompleted = state.spriteCached + done;
      state.currentTask = `正在加载立绘 ${state.spriteCompleted}/${spriteArray.length}...`;
      publish();
    });
    state.spriteCompleted = spriteArray.length;
  } catch (e) {
    console.warn('[preloadService] 图片资源预加载失败:', e);
  } finally {
    state.resourcesDone = true;
    publish();
  }
}

/** 阶段 2：CG（只在保留初始 range 数内预生成，其余仅保存配方按需生成） */
async function preloadCGPhase(
  state: RunState,
  runId: number,
  paragraphs: string[],
  messageId: number,
  characterAppearances: Record<string, string> | undefined,
  publish: () => void,
): Promise<void> {
  const isActive = () => runId === activeRunId;
  try {
    const existingBundle = loadCGRangeRecipeBundle(messageId);

    if (existingBundle && existingBundle.ranges.length > 0) {
      const missing: Array<{ startIndex: number; endIndex: number }> = [];
      let cachedCount = 0;

      for (const range of existingBundle.ranges) {
        const cacheKey = makeRangeCacheKey(messageId, range.startIndex, range.endIndex);
        const cached = await getCGImage(cacheKey);
        if (cached) {
          cachedCount++;
        } else {
          missing.push({ startIndex: range.startIndex, endIndex: range.endIndex });
        }
      }

      const targets = missing.slice(0, CG_PREWARM_RANGE_COUNT);
      state.cgCached = cachedCount;
      state.cgTotal = targets.length;
      state.cgCompleted = 0;
      state.currentTask =
        targets.length > 0
          ? `已缓存 ${cachedCount}/${existingBundle.ranges.length} CG，正在重绘 ${targets.length} 张...`
          : `CG 已就绪（${cachedCount}/${existingBundle.ranges.length} 已缓存）`;
      publish();

      for (const range of targets) {
        if (!isActive()) return;
        try {
          await getCGForRange(messageId, range.startIndex, range.endIndex);
        } catch (e) {
          console.warn(`[preloadService] CG 重绘失败 (${range.startIndex}-${range.endIndex}):`, e);
        }
        if (!isActive()) return;
        state.cgCompleted++;
        state.currentTask = `正在重绘 CG ${state.cgCompleted}/${targets.length}（段落 ${range.startIndex}-${range.endIndex}）`;
        publish();
      }
    } else {
      state.cgTotal = CG_PREWARM_RANGE_COUNT;
      state.cgCompleted = 0;
      state.currentTask = '首次生成，正在分析并预绘最近 CG...';
      publish();

      await triggerCGGenerationWithRange(paragraphs, messageId, characterAppearances, false, {
        maxGenerateCount: CG_PREWARM_RANGE_COUNT,
        onProgress: (done, total) => {
          if (!isActive()) return;
          state.cgTotal = total;
          state.cgCompleted = done;
          state.currentTask = `正在绘制 CG ${done}/${total}...`;
          publish();
        },
      });
    }
  } catch (e) {
    console.warn('[preloadService] CG 预加载失败:', e);
  } finally {
    state.cgDone = true;
    publish();
  }
}

/** 阶段 3：语音（去掉固定睡眠，依赖内层 429 重试；受 VOICE_PREWARM_MAX_COUNT 限制且可取消） */
async function preloadVoicePhase(
  state: RunState,
  runId: number,
  segments: DialogueSegment[],
  voiceConfig: VoiceConfig,
  publish: () => void,
): Promise<void> {
  const isActive = () => runId === activeRunId;
  setPreloadingState(true);
  try {
    const voiceTasks: Array<{ speaker: string; text: string }> = [];
    for (const seg of segments) {
      if (seg.speaker === '旁白') continue;
      if (!voiceConfig.characterVoices[seg.speaker]) continue;
      const ttsText = seg.textJa || seg.text;
      if (!ttsText || !ttsText.trim()) continue;
      voiceTasks.push({ speaker: seg.speaker, text: ttsText });
      if (voiceTasks.length >= VOICE_PREWARM_MAX_COUNT) break;
    }

    state.voiceTotal = voiceTasks.length;
    state.currentTask = voiceTasks.length > 0 ? `准备生成 ${voiceTasks.length} 条语音...` : '无需预生成语音';
    publish();

    let cachedCount = 0;
    for (let i = 0; i < voiceTasks.length; i++) {
      // 用户开始游玩或收到取消信号时立即停止后台预热
      if (!isActive() || isPreloadCancelled()) break;

      const task = voiceTasks[i];
      const voiceSettings = voiceConfig.characterVoices[task.speaker];
      try {
        const usedCache = await synthesizeAndPreloadVoice(task.text, voiceSettings, voiceConfig);
        if (usedCache) cachedCount++;
      } catch (e) {
        console.warn(`[preloadService] 语音 ${i + 1} 生成失败:`, e);
      }

      if (!isActive()) break;
      state.voiceCached = cachedCount;
      state.voiceCompleted = i + 1;
      state.currentTask = `正在生成语音 ${i + 1}/${voiceTasks.length}（${task.speaker}）`;
      publish();
    }
  } catch (e) {
    console.warn('[preloadService] 语音预加载失败:', e);
  } finally {
    setPreloadingState(false);
    state.voiceDone = true;
    publish();
  }
}

export async function preloadFloorResources(
  segments: DialogueSegment[],
  messageId: number,
  resourceConfig: ResourceConfig,
  characterAppearances?: Record<string, string>,
  cgPreloadEnabled?: boolean,
  voicePreloadEnabled?: boolean,
  runId: number = activeRunId,
): Promise<boolean> {
  const cgSettings = loadCGSettings();
  const voiceConfig = resourceConfig.voices;

  const cgEnabled = !!(
    cgPreloadEnabled &&
    cgSettings.enabled &&
    cgSettings.directorLLM.apiKey &&
    cgSettings.novelAI.apiKey
  );
  const voiceEnabled = !!(voicePreloadEnabled && voiceConfig?.enabled && voiceConfig.apiKey && voiceConfig.characterVoices);

  const state: RunState = {
    phase: 'checking',
    overallPercent: 0,
    cgTotal: 0,
    cgCompleted: 0,
    cgCached: 0,
    voiceTotal: 0,
    voiceCompleted: 0,
    voiceCached: 0,
    bgTotal: 0,
    bgCompleted: 0,
    bgCached: 0,
    spriteTotal: 0,
    spriteCompleted: 0,
    spriteCached: 0,
    currentTask: '正在检查已有资源...',
    resourcesDone: false,
    cgDone: !cgEnabled,
    voiceDone: !voiceEnabled,
    cgEnabled,
    voiceEnabled,
  };

  /** 唯一进度推送出口：三阶段并发时原子更新整包进度 */
  const publish = () => {
    if (runId !== activeRunId) return;

    const parts: Array<{ weight: number; fraction: number }> = [];
    const resourceTotal = state.bgTotal + state.spriteTotal;
    parts.push({
      weight: 0.2,
      fraction: state.resourcesDone
        ? 1
        : resourceTotal > 0
          ? (state.bgCompleted + state.spriteCompleted) / resourceTotal
          : 0,
    });
    if (cgEnabled) {
      parts.push({
        weight: 0.4,
        fraction: state.cgDone ? 1 : state.cgTotal > 0 ? Math.min(1, state.cgCompleted / state.cgTotal) : 0,
      });
    }
    if (voiceEnabled) {
      parts.push({
        weight: 0.4,
        fraction: state.voiceDone ? 1 : state.voiceTotal > 0 ? Math.min(1, state.voiceCompleted / state.voiceTotal) : 0,
      });
    }

    const weightSum = parts.reduce((sum, p) => sum + p.weight, 0);
    const rawPercent =
      weightSum > 0 ? (parts.reduce((sum, p) => sum + p.weight * p.fraction, 0) / weightSum) * 100 : 0;
    // 单调不回退
    state.overallPercent = Math.max(state.overallPercent, Math.round(rawPercent));

    if (state.error) {
      state.phase = 'error';
    } else if (state.resourcesDone && state.cgDone && state.voiceDone) {
      state.phase = 'done';
    } else if (!state.resourcesDone) {
      state.phase = 'resources';
    } else if (cgEnabled && !state.cgDone) {
      state.phase = 'cg';
    } else {
      state.phase = 'voice';
    }

    notifyProgress({
      phase: state.phase,
      overallPercent: state.overallPercent,
      cgTotal: state.cgTotal,
      cgCompleted: state.cgCompleted,
      cgCached: state.cgCached,
      voiceTotal: state.voiceTotal,
      voiceCompleted: state.voiceCompleted,
      voiceCached: state.voiceCached,
      bgTotal: state.bgTotal,
      bgCompleted: state.bgCompleted,
      bgCached: state.bgCached,
      spriteTotal: state.spriteTotal,
      spriteCompleted: state.spriteCompleted,
      spriteCached: state.spriteCached,
      currentTask: state.currentTask,
      error: state.error,
    });
  };

  publish();

  try {
    const jobs: Array<Promise<void>> = [
      preloadResourcesPhase(state, runId, segments, resourceConfig, publish),
    ];
    if (cgEnabled) {
      jobs.push(
        preloadCGPhase(
          state,
          runId,
          buildDirectorParagraphs(segments),
          messageId,
          characterAppearances,
          publish,
        ),
      );
    }
    if (voiceEnabled && voiceConfig) {
      jobs.push(preloadVoicePhase(state, runId, segments, voiceConfig, publish));
    }

    await Promise.all(jobs);
  } catch (e) {
    state.error = e instanceof Error ? e.message : String(e);
    console.error('[preloadService] 预加载失败:', state.error);
    state.resourcesDone = true;
    state.cgDone = true;
    state.voiceDone = true;
  }

  publish();

  if (!state.error) {
    state.currentTask = '加载完成！开始您的旅程吧～';
    publish();
  }

  return !state.error;
}

/**
 * 取消当前预加载：语音取消 + CG 中止 + 递增 run token（旧 run 回调静默丢弃）
 */
export function cancelPreload(): void {
  activeRunId++;

  try {
    cancelPreloadVoice();
  } catch (e) {
    console.warn('[preloadService] 取消语音预加载失败:', e);
  }

  try {
    abortCGGeneration();
  } catch (e) {
    console.warn('[preloadService] 中止 CG 生成失败:', e);
  }

  notifyProgress(emptyProgress());
}

/**
 * 仅当没有任何进度订阅者时才取消预加载。
 *
 * 酒馆可能在同一次会话里挂载多个前端界面实例（多个楼层/重复渲染），它们共用本模块单例。
 * 若某个实例卸载就无条件 cancelPreload，会把其它仍在运行的实例的 run token 失效，
 * 导致进度卡在 0（旧 run 的 publish 被静默丢弃）。因此卸载时只在「最后一个订阅者」离开才取消。
 */
export function cancelPreloadIfUnused(): void {
  if (progressListeners.size === 0) {
    cancelPreload();
  }
}

export async function startPreload(
  resourceConfig: ResourceConfig,
  cgPreloadEnabled?: boolean,
  voicePreloadEnabled?: boolean,
): Promise<boolean> {
  // 若已有旧 run 在跑（多实例/重复触发），先取消它，避免 NovelAI 并发与资源浪费
  if (activeRunId !== 0) {
    try {
      cancelPreloadVoice();
    } catch (e) {
      console.warn('[preloadService] 取消失败（语音）:', e);
    }
    try {
      abortCGGeneration();
    } catch (e) {
      console.warn('[preloadService] 取消失败（CG）:', e);
    }
  }

  const runId = ++activeRunId;
  // 每次新 run 复位语音取消标志
  resetPreloadVoice();

  try {
    if (typeof (window as any).getChatMessages !== 'function') {
      console.error('[preloadService] getChatMessages 函数不可用');
      throw new Error('getChatMessages 函数不可用');
    }

    if (typeof (window as any).getCurrentMessageId !== 'function') {
      console.error('[preloadService] getCurrentMessageId 函数不可用');
      throw new Error('getCurrentMessageId 函数不可用');
    }

    const getChatMessages = (window as any).getChatMessages;
    const getCurrentMessageId = (window as any).getCurrentMessageId;

    const messageId = getCurrentMessageId();

    if (messageId < 0) {
      console.warn('[preloadService] 无法获取当前消息 ID，跳过预加载');
      if (runId === activeRunId) notifySkipped('未找到当前楼层，跳过预加载');
      return false;
    }

    const messages = getChatMessages(messageId);

    if (messages.length === 0) {
      console.warn('[preloadService] 当前消息未找到，跳过预加载');
      if (runId === activeRunId) notifySkipped('当前楼层为空，跳过预加载');
      return false;
    }

    const result = parseDialogueScript(messages[0].message);

    if (result.segments.length === 0) {
      console.warn('[preloadService] 无有效段落，跳过预加载');
      if (runId === activeRunId) notifySkipped('无有效段落，跳过预加载');
      return false;
    }

    return await preloadFloorResources(
      result.segments,
      messageId,
      resourceConfig,
      resourceConfig.characterAppearances,
      cgPreloadEnabled,
      voicePreloadEnabled,
      runId,
    );
  } catch (e) {
    console.error('[preloadService] 预加载启动失败:', e);
    if (runId === activeRunId) {
      const errorProgress = emptyProgress();
      errorProgress.phase = 'error';
      errorProgress.error = e instanceof Error ? e.message : String(e);
      notifyProgress(errorProgress);
    }
    return false;
  }
}
