/**
 * CG 缓存服务（服务器存储）
 *
 * 生成的 CG 上传到酒馆服务器（user/images/novelui_cg），所有端共享；
 * 读取时用服务器地址（浏览器自带 HTTP 缓存负责速度），不再使用 IndexedDB。
 *
 * Vibe 参考图与编码仍留在 IndexedDB：它们是生成 CG 的输入素材，不属于本功能范围。
 */

import {
  deleteMedia,
  forgetMedia,
  invalidateMediaList,
  isServerImage,
  listMediaNames,
  mediaRelativePath,
  MEDIA_TYPE,
  rememberMedia,
  serverUrl,
  splitDataUrl,
  uploadMedia,
} from './serverStore';

const DB_NAME = 'quiet_editor_cg_cache';
const DB_VERSION = 4;
const LEGACY_CG_STORE_NAME = 'cg_images';
const VIBE_STORE_NAME = 'vibe_images';
const VIBE_ENCODING_STORE_NAME = 'vibe_encodings';

/** CG 在酒馆服务器上的子目录 */
const CG_FOLDER = 'novelui_cg';

/**
 * 本会话内刚上传过的 key → 时间戳。
 * 同一 key 被重新生成时会覆盖服务器同名文件，加一个查询参数让浏览器/内存缓存不返回旧图。
 * （酒馆静态资源是 max-age=0，跨设备读取本身会重新校验。）
 */
const freshStamps = new Map<string, number>();

/** 获取 IndexedDB 实例（仅 Vibe 使用） */
function openDB(): Promise<IDBDatabase> {
  return new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);

    request.onupgradeneeded = () => {
      const db = request.result;
      // CG 已改存酒馆服务器，删掉遗留的本地 store 释放空间
      if (db.objectStoreNames.contains(LEGACY_CG_STORE_NAME)) {
        db.deleteObjectStore(LEGACY_CG_STORE_NAME);
      }
      if (!db.objectStoreNames.contains(VIBE_STORE_NAME)) {
        db.createObjectStore(VIBE_STORE_NAME);
      }
      if (!db.objectStoreNames.contains(VIBE_ENCODING_STORE_NAME)) {
        db.createObjectStore(VIBE_ENCODING_STORE_NAME);
      }
    };

    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error);
  });
}

/** 是否已开始清理遗留的本地 CG store */
let legacyCleanupStarted = false;

/** CG 已迁到服务器，打开一次 DB 触发版本升级，顺带删掉遗留的 cg_images store */
function cleanupLegacyCgStore(): void {
  if (legacyCleanupStarted) return;
  legacyCleanupStarted = true;
  void openDB()
    .then(db => db.close())
    .catch(() => {
      /* 旧库不存在时忽略 */
    });
}

/** 生成缓存 key: cg_{messageId}_{paragraphIndex} */
export function makeCacheKey(messageId: number, paragraphIndex: number): string {
  return `cg_${messageId}_${paragraphIndex}`;
}

/** 生成范围缓存 key: cg_{messageId}_range_{startIndex}_{endIndex} */
export function makeRangeCacheKey(messageId: number, startIndex: number, endIndex: number): string {
  return `cg_${messageId}_range_${startIndex}_${endIndex}`;
}

// ====== CG 图片存取（酒馆服务器）======

/**
 * 存入 CG 图片。
 * @param key 缓存 key（同时作为服务器文件名，字符集安全）
 * @param image 生成的图片：data URL（待上传）或已是服务器地址（直接透传）
 * @returns 可用的图片地址（服务器 URL；上传失败时原样返回输入值本次兜底）
 */
export async function putCGImage(key: string, image: string): Promise<string> {
  cleanupLegacyCgStore();
  if (!image) return '';
  // CGViewer 选择已有版本时会回传服务器地址，无需重复上传
  if (isServerImage(image)) return image;

  const parsed = splitDataUrl(image);
  if (!parsed) {
    console.warn('[cgCache] 无法识别的图片格式，跳过服务器存储:', key);
    return image;
  }

  try {
    const path = await uploadMedia({
      base64: parsed.base64,
      format: parsed.format,
      folder: CG_FOLDER,
      filename: key,
    });
    rememberMedia(CG_FOLDER, MEDIA_TYPE.IMAGE, `${key}.${parsed.format}`);
    freshStamps.set(key, Date.now());
    return serverUrl(path);
  } catch (e) {
    console.error('[cgCache] CG 上传服务器失败（本次仍可显示）:', e);
    return image;
  }
}

/** 读取 CG 图片地址，服务器上不存在则返回 null */
export async function getCGImage(key: string): Promise<string | null> {
  cleanupLegacyCgStore();
  try {
    const names = await listMediaNames(CG_FOLDER, MEDIA_TYPE.IMAGE);
    for (const format of ['png', 'webp', 'jpg']) {
      const fileName = `${key}.${format}`;
      if (names.has(fileName)) {
        const stamp = freshStamps.get(key);
        const url = serverUrl(mediaRelativePath(CG_FOLDER, fileName));
        return stamp ? `${url}?t=${stamp}` : url;
      }
    }
    return null;
  } catch (e) {
    console.warn('[cgCache] 读取 CG 目录失败:', e);
    return null;
  }
}

/** 删除指定 key 的 CG 图片（兼容历史可能存在的不同扩展名） */
export async function deleteCGImage(key: string): Promise<void> {
  freshStamps.delete(key);
  for (const format of ['png', 'webp', 'jpg']) {
    const fileName = `${key}.${format}`;
    try {
      await deleteMedia(mediaRelativePath(CG_FOLDER, fileName));
      forgetMedia(CG_FOLDER, MEDIA_TYPE.IMAGE, fileName);
    } catch {
      /* 不存在时忽略 */
    }
  }
}

// ====== Vibe 图片存取（IndexedDB）======

/** 删除指定 key 的 Vibe 图片 */
export async function deleteVibeImage(key: string): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(VIBE_STORE_NAME, 'readwrite');
    const store = tx.objectStore(VIBE_STORE_NAME);
    const request = store.delete(key);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
    tx.oncomplete = () => db.close();
  });
}

// ====== Vibe 编码存取（大字段，从全局变量下沉到 IndexedDB）======

/** 存入 Vibe 编码（V4.5 Vibe Bundle 的 encoding） */
export async function putVibeEncoding(key: string, encoding: string): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(VIBE_ENCODING_STORE_NAME, 'readwrite');
    const store = tx.objectStore(VIBE_ENCODING_STORE_NAME);
    const request = store.put(encoding, key);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
    tx.oncomplete = () => db.close();
  });
}

/** 删除指定 key 的 Vibe 编码 */
export async function deleteVibeEncoding(key: string): Promise<void> {
  const db = await openDB();
  return new Promise((resolve, reject) => {
    const tx = db.transaction(VIBE_ENCODING_STORE_NAME, 'readwrite');
    const store = tx.objectStore(VIBE_ENCODING_STORE_NAME);
    const request = store.delete(key);
    request.onsuccess = () => resolve();
    request.onerror = () => reject(request.error);
    tx.oncomplete = () => db.close();
  });
}

/**
 * 批量读取一个 store 的多个 key，共用一次连接与事务（避免每个 key 各开一次 IndexedDB）。
 * @returns key -> 字符串值 的映射（不存在或非字符串的 key 不会出现在映射里）
 */
function getManyFromStore(storeName: string, keys: string[]): Promise<Map<string, string>> {
  const result = new Map<string, string>();
  if (keys.length === 0) return Promise.resolve(result);
  return openDB().then(
    db =>
      new Promise<Map<string, string>>(resolve => {
        const tx = db.transaction(storeName, 'readonly');
        const store = tx.objectStore(storeName);
        for (const key of keys) {
          const request = store.get(key);
          request.onsuccess = () => {
            if (typeof request.result === 'string') result.set(key, request.result);
          };
        }
        const finish = () => {
          db.close();
          resolve(result);
        };
        tx.oncomplete = finish;
        tx.onerror = finish;
        tx.onabort = finish;
      }),
  );
}

/** 批量读取 Vibe 图片 base64 */
export function getVibeImages(keys: string[]): Promise<Map<string, string>> {
  return getManyFromStore(VIBE_STORE_NAME, keys);
}

/** 批量读取 Vibe 编码 */
export function getVibeEncodings(keys: string[]): Promise<Map<string, string>> {
  return getManyFromStore(VIBE_ENCODING_STORE_NAME, keys);
}

// ====== 清理操作（酒馆服务器）======

/** 删除指定文件名集合，返回成功删除的数量 */
async function deleteCGNames(names: string[]): Promise<number> {
  let deleted = 0;
  for (const name of names) {
    try {
      await deleteMedia(mediaRelativePath(CG_FOLDER, name));
      forgetMedia(CG_FOLDER, MEDIA_TYPE.IMAGE, name);
      deleted++;
    } catch (e) {
      console.warn('[cgCache] 删除 CG 失败:', name, e);
    }
  }
  return deleted;
}

/** 清理指定楼层的所有 CG 缓存 */
export async function clearFloorCGCache(messageId: number): Promise<void> {
  const names = await listMediaNames(CG_FOLDER, MEDIA_TYPE.IMAGE, true);
  const prefix = `cg_${messageId}_`;
  await deleteCGNames([...names].filter(name => name.startsWith(prefix)));
}

/** 清理所有 CG 缓存 */
export async function clearAllCGCache(): Promise<void> {
  const names = await listMediaNames(CG_FOLDER, MEDIA_TYPE.IMAGE, true);
  await deleteCGNames([...names]);
  invalidateMediaList(CG_FOLDER, MEDIA_TYPE.IMAGE);
}

/** 自动清理：保留最近 N 楼的 CG 缓存，清理更旧的 */
export async function autoCleanCache(keepRecentFloors: number = 50): Promise<number> {
  try {
    const names = [...(await listMediaNames(CG_FOLDER, MEDIA_TYPE.IMAGE, true))];
    const entries = names
      .map(name => {
        const match = name.match(/^cg_(\d+)_/);
        return match ? { name, messageId: parseInt(match[1], 10) } : null;
      })
      .filter((item): item is { name: string; messageId: number } => item !== null);

    // 按 messageId 降序排序
    entries.sort((a, b) => b.messageId - a.messageId);

    // 保留最近 N 楼（去重 messageId）
    const keptMessageIds = new Set<number>();
    const toDelete: string[] = [];
    for (const item of entries) {
      if (keptMessageIds.size < keepRecentFloors) {
        keptMessageIds.add(item.messageId);
      } else if (!keptMessageIds.has(item.messageId)) {
        toDelete.push(item.name);
      }
    }

    return await deleteCGNames(toDelete);
  } catch (e) {
    console.warn('[cgCache] 自动清理失败:', e);
    return 0;
  }
}
