/**
 * LoadingScreen - 可爱的资源预加载界面
 * 显示 CG、语音、背景和立绘的生成进度，带有跳动的低饱和彩色点动画
 */

import React from 'react';
import type { PreloadProgress } from '../services/preloadService';

interface LoadingScreenProps {
  progress: PreloadProgress;
  onClose?: () => void;
}

export const LoadingScreen: React.FC<LoadingScreenProps> = ({ progress, onClose }) => {
  const {
    phase,
    overallPercent,
    cgTotal,
    cgCompleted,
    voiceTotal,
    voiceCompleted,
    bgTotal,
    bgCompleted,
    spriteTotal,
    spriteCompleted,
    currentTask,
    error,
  } = progress;

  // 计算总体进度百分比：优先使用 service 计算好的加权进度，回退到简单求和
  const totalTasks = cgTotal + voiceTotal + bgTotal + spriteTotal;
  const completedTasks = cgCompleted + voiceCompleted + bgCompleted + spriteCompleted;
  const fallbackPercentage = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
  const percentage =
    typeof overallPercent === 'number'
      ? Math.max(0, Math.min(100, Math.round(overallPercent)))
      : fallbackPercentage;

  return (
    <div className="fixed inset-0 z-[100] flex flex-col items-center justify-center bg-[#f4f6f8] text-[#1e242b] transition-opacity duration-300 animate-in fade-in select-none">
      {/* 极简呼吸背景微光 */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-[600px] h-[600px] rounded-full bg-[#dde3e8]/50 blur-[120px] pointer-events-none" />
      </div>

      {/* 主浮动面板：参考图1/图3的现代扁平大圆角卡片 */}
      <div className="relative z-10 flex flex-col items-center w-full max-w-[460px] mx-4 p-8 rounded-[36px] bg-white border border-white shadow-[0_20px_60px_rgba(30,36,43,0.08)]">
        {/* 顶部标题区 */}
        <div className="flex flex-col items-center mb-6">
          <div className="flex items-center gap-2 mb-1">
            <span className="w-2.5 h-2.5 rounded-full bg-[#526070] animate-pulse" />
            <h2 className="font-sans-m3 text-lg font-bold text-[#1e242b] tracking-tight">
              资源加载与构筑
            </h2>
          </div>
          <span className="font-mono-retro text-[9px] text-[#84919e] uppercase tracking-wider">
            MATERIAL 3 PRELOADING SERVICE
          </span>
        </div>

        {/* 错误状态 */}
        {error ? (
          <div className="flex flex-col items-center gap-2 my-4">
            <span className="text-4xl">⚠️</span>
            <p className="text-xs text-[#c4384c] text-center">{error}</p>
          </div>
        ) : phase === 'done' ? (
          <div className="flex flex-col items-center gap-2 my-4">
            <span className="text-4xl">✨</span>
            <p className="font-sans-m3 text-sm font-semibold text-[#1e242b]">就绪完成</p>
          </div>
        ) : (
          <div className="w-full flex flex-col gap-6">
            {/* 进度条与百分比 */}
            <div className="flex flex-col gap-2">
              <div className="flex justify-between items-center text-xs font-mono-retro">
                <span className="text-[#747f8d] truncate max-w-[280px]">
                  {currentTask || '正在准备剧场资源…'}
                </span>
                <span className="font-bold text-[#526070] text-sm">
                  {percentage}%
                </span>
              </div>

              {/* 现代极简扁平条 */}
              <div className="relative h-2 w-full rounded-full bg-[#edf1f4] overflow-hidden">
                <div
                  className="absolute left-0 top-0 h-full rounded-full bg-[#526070] transition-all duration-300 ease-out"
                  style={{ width: `${percentage}%` }}
                />
              </div>
            </div>

            {/* 四类资源状态芯片徽章网格 (参考图1/图3微卡片) */}
            <div className="grid grid-cols-4 gap-2">
              <div className="flex flex-col items-center p-2.5 rounded-[18px] bg-[#f7f9fa] border border-[#edf1f4]">
                <span className="font-mono-retro text-[8px] uppercase tracking-wider text-[#84919e]">BG</span>
                <span className="font-mono-retro text-xs font-bold text-[#1e242b] mt-0.5">
                  {bgCompleted}/{bgTotal}
                </span>
              </div>
              <div className="flex flex-col items-center p-2.5 rounded-[18px] bg-[#f7f9fa] border border-[#edf1f4]">
                <span className="font-mono-retro text-[8px] uppercase tracking-wider text-[#84919e]">SPRITE</span>
                <span className="font-mono-retro text-xs font-bold text-[#1e242b] mt-0.5">
                  {spriteCompleted}/{spriteTotal}
                </span>
              </div>
              <div className="flex flex-col items-center p-2.5 rounded-[18px] bg-[#f7f9fa] border border-[#edf1f4]">
                <span className="font-mono-retro text-[8px] uppercase tracking-wider text-[#84919e]">CG</span>
                <span className="font-mono-retro text-xs font-bold text-[#1e242b] mt-0.5">
                  {cgCompleted}/{cgTotal}
                </span>
              </div>
              <div className="flex flex-col items-center p-2.5 rounded-[18px] bg-[#f7f9fa] border border-[#edf1f4]">
                <span className="font-mono-retro text-[8px] uppercase tracking-wider text-[#84919e]">VOICE</span>
                <span className="font-mono-retro text-xs font-bold text-[#1e242b] mt-0.5">
                  {voiceCompleted}/{voiceTotal}
                </span>
              </div>
            </div>
          </div>
        )}

        {/* 开始游玩胶囊按钮 */}
        {onClose && (
          <button
            onClick={onClose}
            className="mt-6 w-full py-3 rounded-full bg-[#526070] hover:bg-[#3d4a58] text-white font-sans-m3 text-xs font-semibold tracking-wider transition-all cursor-pointer shadow-sm active:scale-[0.98]"
          >
            直接进入剧场 ↵
          </button>
        )}
      </div>
    </div>
  );
};
