// ====== 导演 LLM API 方案 ======
const DirectorApiProfileSection: React.FC<{
  directorLLM: { endpoint: string; apiKey: string; model: string };
  onUpdate: (updater: (prev: CGGenerationSettings) => CGGenerationSettings) => void;
  playSfx: () => void;
}> = ({ directorLLM, onUpdate, playSfx }) => {
  const [profiles, setProfiles] = useState<DirectorApiProfile[]>([]);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [newName, setNewName] = useState('');
  const [editingId, setEditingId] = useState<string | null>(null);
  const [editingName, setEditingName] = useState('');
  const importInputRef = useRef<HTMLInputElement>(null);

  const refresh = useCallback(() => {
    const storage = ensureBuiltinDirectorApiProfile();
    setProfiles(storage.profiles);
    setActiveId(storage.activeProfileId);
  }, []);

  useEffect(() => {
    refresh();
  }, [refresh]);

  // 选中项失效（被删/外部切换）时回落到当前启用或首个方案
  useEffect(() => {
    if (selectedId && profiles.some(p => p.id === selectedId)) return;
    setSelectedId(activeId ?? profiles[0]?.id ?? null);
  }, [profiles, activeId, selectedId]);

  const selected = profiles.find(p => p.id === selectedId) ?? null;

  // 应用/删除方案后把运行时设置同步回父组件状态，使下方连接字段立即刷新
  const syncFromSettings = () => onUpdate(() => loadCGSettings());
  const reload = () => {
    const storage = loadDirectorApiProfileStorage();
    setProfiles(storage.profiles);
    setActiveId(storage.activeProfileId);
  };

  const handleApply = (id: string) => {
    playSfx();
    applyDirectorApiProfile(id);
    reload();
    syncFromSettings();
  };

  const handleCreate = () => {
    const name = newName.trim();
    if (!name) return;
    playSfx();
    createDirectorApiProfile(name);
    reload();
    setNewName('');
  };

  // 把下方正在编辑的连接配置写回当前启用方案（避免直接编辑后切换方案丢失）
  const handleSaveCurrent = () => {
    if (!selected) return;
    playSfx();
    updateDirectorApiProfile(selected.id, p => ({
      ...p,
      config: { endpoint: directorLLM.endpoint, apiKey: directorLLM.apiKey, model: directorLLM.model },
    }));
    reload();
  };

  const handleExport = () => {
    if (!selected) return;
    const json = exportDirectorApiProfile(selected.id);
    if (!json) return;
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = `${selected.name}.json`;
    anchor.click();
    URL.revokeObjectURL(url);
  };

  const handleImportFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (importInputRef.current) importInputRef.current.value = '';
    if (!file) return;
    try {
      importDirectorApiProfile(await file.text());
      reload();
    } catch (err: any) {
      notifyError(`导入失败: ${err.message}`);
    }
  };

  return (
    <>
      <SectionHeader icon={<Server size={13} />} title="API 方案" subtitle="DIRECTOR_API_PROFILE" />
      <span className="font-mono-retro text-[9px] text-[var(--color-cozy-muted)] tracking-[0.1em] -mt-2">
        保存导演 LLM 的地址 / Key / 模型；应用后写入下方连接配置。
      </span>

      <div className="flex items-center gap-2">
        <select
          value={selectedId ?? ''}
          onChange={e => {
            playSfx();
            setSelectedId(e.target.value || null);
          }}
          className="flex-1 px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200 cursor-pointer"
        >
          <option value="">-- 选择方案 --</option>
          {profiles.map(p => (
            <option key={p.id} value={p.id}>
              {p.name}
              {p.id === activeId ? '（当前）' : ''}
            </option>
          ))}
        </select>
        {selected && selected.id === activeId && (
          <span className="flex items-center gap-1 px-2 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[9px] font-mono-retro tracking-[0.1em]">
            <Check size={10} /> 已启用
          </span>
        )}
        {selected && selected.id !== activeId && (
          <button
            onClick={() => handleApply(selected.id)}
            className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[10px] font-mono-retro tracking-[0.15em] hover:shadow-[0_2px_8px_rgba(221,184,176,0.4)] transition-all duration-200 cursor-pointer"
          >
            <Check size={10} /> 应用
          </button>
        )}
      </div>

      {selected && selected.id === activeId && (
        <button
          onClick={handleSaveCurrent}
          className="self-start flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
        >
          <Check size={10} /> 保存当前连接配置到本方案
        </button>
      )}

      {selected && (
        <>
          <div className="flex gap-2">
            <button
              onClick={() => {
                playSfx();
                duplicateDirectorApiProfile(selected.id);
                reload();
              }}
              className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
            >
              复制
            </button>
            <button
              onClick={() => {
                setEditingId(selected.id);
                setEditingName(selected.name);
              }}
              className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
            >
              <Pencil size={10} /> 重命名
            </button>
            <button
              onClick={() => {
                if (!selected.builtin) {
                  playSfx();
                  deleteDirectorApiProfile(selected.id);
                  reload();
                  syncFromSettings();
                }
              }}
              disabled={selected.builtin}
              title={selected.builtin ? '内置方案不可删除' : '删除方案'}
              className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro hover:text-[#b86f6f] transition-all duration-200 cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <Trash2 size={10} /> 删除
            </button>
            <button
              onClick={handleExport}
              className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
            >
              <Download size={10} /> 导出
            </button>
            <button
              onClick={() => importInputRef.current?.click()}
              className="flex items-center gap-1 px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
            >
              <Upload size={10} /> 导入
            </button>
          </div>

          {editingId === selected.id && (
            <div className="flex gap-2">
              <input
                type="text"
                value={editingName}
                onChange={e => setEditingName(e.target.value)}
                className="flex-1 px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200"
              />
              <button
                onClick={() => {
                  if (editingName.trim()) {
                    renameDirectorApiProfile(selected.id, editingName.trim());
                    reload();
                  }
                  setEditingId(null);
                }}
                className="px-3 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[10px] font-mono-retro tracking-[0.15em] cursor-pointer"
              >
                确认
              </button>
              <button
                onClick={() => setEditingId(null)}
                className="px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro cursor-pointer"
              >
                取消
              </button>
            </div>
          )}
        </>
      )}

      {/* 新建方案 */}
      <div className="flex gap-2">
        <input
          type="text"
          value={newName}
          onChange={e => setNewName(e.target.value)}
          placeholder="新方案名称（以当前连接配置为初始值）..."
          className="flex-1 px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 placeholder:text-[var(--color-cozy-muted)] placeholder:opacity-50 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200"
        />
        <button
          onClick={handleCreate}
          className="px-3 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[10px] font-mono-retro tracking-[0.15em] hover:shadow-[0_2px_8px_rgba(221,184,176,0.4)] transition-all duration-200 cursor-pointer"
        >
          <Plus size={12} />
        </button>
      </div>

      {/* 隐藏的导入文件 input */}
      <input
        ref={importInputRef}
        type="file"
        accept=".json,application/json"
        className="hidden"
        onChange={handleImportFile}
      />
    </>
  );
};

// ====== 通用 Tab ======
const GeneralTab: React.FC<{
  cgSettings: CGGenerationSettings;
  onUpdate: (updater: (prev: CGGenerationSettings) => CGGenerationSettings) => void;
  onClearCache: () => void;
  isClearingCache: boolean;
  playSfx: () => void;
}> = ({ cgSettings, onUpdate, onClearCache, isClearingCache, playSfx }) => {
  const [modelList, setModelList] = useState<string[]>([]);
  const [isLoadingModels, setIsLoadingModels] = useState(false);
  const [modelError, setModelError] = useState<string>('');

  const handleFetchModels = useCallback(async () => {
    const { endpoint, apiKey } = cgSettings.directorLLM;
    if (!endpoint || !apiKey) {
      setModelError('请先填写 API 地址和 Key');
      return;
    }

    setIsLoadingModels(true);
    setModelError('');

    try {
      let modelsUrl = endpoint.trim();
      if (modelsUrl.endsWith('/chat/completions')) {
        modelsUrl = modelsUrl.replace('/chat/completions', '/models');
      } else {
        if (!modelsUrl.endsWith('/')) modelsUrl += '/';
        if (modelsUrl.endsWith('/v1/')) {
          modelsUrl += 'models';
        } else {
          modelsUrl += 'v1/models';
        }
      }

      const response = await fetch(modelsUrl, {
        method: 'GET',
        headers: { Authorization: `Bearer ${apiKey}` },
      });

      if (!response.ok) {
        throw new Error(`请求失败 (${response.status})`);
      }

      const data = await response.json();
      const models: string[] = (data?.data || [])
        .map((m: any) => m.id)
        .filter((id: string) => !!id)
        .sort();

      if (models.length === 0) {
        setModelError('未找到可用模型');
      } else {
        setModelList(models);
        setModelError('');
      }
    } catch (e: any) {
      setModelError(e?.message || '获取模型列表失败');
    } finally {
      setIsLoadingModels(false);
    }
  }, [cgSettings.directorLLM.endpoint, cgSettings.directorLLM.apiKey]);

  return (
    <div className="flex flex-col gap-4">
      {/* 引擎开关控制网格 */}
      <div className="p-4 rounded-2xl bg-white border border-[#edf1f4] shadow-[0_2px_10px_rgba(30,36,43,0.03)] flex flex-col gap-3">
        <div className="flex items-center justify-between">
          <span className="font-sans-m3 text-[13px] font-bold text-[#1e242b]">
            服务开关与全局行为
          </span>
          <span className="font-sans-m3 text-[10.5px] text-[#84919e]">
            控制自动生成与预加载流程
          </span>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-1">
          <div className="p-3 rounded-xl bg-[#edf1f4]/60 flex items-center justify-between gap-3">
            <div className="flex flex-col">
              <span className="font-sans-m3 text-[12.5px] font-semibold text-[#1e242b]">
                启用 CG 生成
              </span>
              <span className="text-[10px] text-[#84919e] font-sans-m3">
                总开关（关闭后停止所有后台出图）
              </span>
            </div>
            <ToggleSwitch
              checked={cgSettings.enabled}
              onChange={checked => onUpdate(prev => ({ ...prev, enabled: checked }))}
            />
          </div>

          <div className="p-3 rounded-xl bg-[#edf1f4]/60 flex items-center justify-between gap-3">
            <div className="flex flex-col">
              <span className="font-sans-m3 text-[12.5px] font-semibold text-[#1e242b]">
                自动重绘
              </span>
              <span className="text-[10px] text-[#84919e] font-sans-m3">
                本地缓存丢失时自动重新生成
              </span>
            </div>
            <ToggleSwitch
              checked={cgSettings.autoRegenerate !== false}
              onChange={checked => onUpdate(prev => ({ ...prev, autoRegenerate: checked }))}
            />
          </div>

          <div className="p-3 rounded-xl bg-[#edf1f4]/60 flex items-center justify-between gap-3">
            <div className="flex flex-col">
              <span className="font-sans-m3 text-[12.5px] font-semibold text-[#1e242b]">
                CG 预加载
              </span>
              <span className="text-[10px] text-[#84919e] font-sans-m3">
                翻楼时提前生成当楼所需剧照
              </span>
            </div>
            <ToggleSwitch
              checked={cgSettings.preloadEnabled ?? false}
              onChange={checked => onUpdate(prev => ({ ...prev, preloadEnabled: checked }))}
            />
          </div>

          <div className="p-3 rounded-xl bg-[#edf1f4]/60 flex items-center justify-between gap-3">
            <div className="flex flex-col">
              <span className="font-sans-m3 text-[12.5px] font-semibold text-[#1e242b]">
                全 CG 覆盖模式
              </span>
              <span className="text-[10px] text-[#84919e] font-sans-m3">
                所有文段均展示对应或延续剧照
              </span>
            </div>
            <ToggleSwitch
              checked={cgSettings.fullCoverageMode !== false}
              onChange={checked => onUpdate(prev => ({ ...prev, fullCoverageMode: checked }))}
            />
          </div>
        </div>
      </div>

      {/* 导演 LLM 方案选择 */}
      <div className="p-4 rounded-2xl bg-white border border-[#edf1f4] shadow-[0_2px_10px_rgba(30,36,43,0.03)] flex flex-col gap-3">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Server size={15} className="text-[#526070]" />
            <span className="font-sans-m3 text-[13.5px] font-bold text-[#1e242b]">
              导演 LLM 方案与凭据
            </span>
          </div>
          <span className="font-sans-m3 text-[10.5px] text-[#84919e]">
            用于剧本解析、分段切分与镜头提示词策划
          </span>
        </div>

        <DirectorApiProfileSection directorLLM={cgSettings.directorLLM} onUpdate={onUpdate} playSfx={playSfx} />

        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 pt-2 border-t border-[#edf1f4]">
          <InputField
            label="API 基础地址 (Endpoint)"
            placeholder="https://api.openai.com/v1"
            value={cgSettings.directorLLM.endpoint}
            onChange={val => onUpdate(prev => ({ ...prev, directorLLM: { ...prev.directorLLM, endpoint: val } }))}
            type="url"
          />
          <InputField
            label="API Key"
            placeholder="sk-..."
            value={cgSettings.directorLLM.apiKey}
            onChange={val => onUpdate(prev => ({ ...prev, directorLLM: { ...prev.directorLLM, apiKey: val } }))}
            type="password"
          />
        </div>

        {/* 模型选择 */}
        <div className="flex flex-col gap-1.5 pt-1">
          <div className="flex items-center justify-between">
            <label className="font-sans-m3 text-[11px] font-semibold text-[#526070]">
              导演模型 (Model)
            </label>
            {modelError && (
              <span className="font-sans-m3 text-[10px] text-[#c4384c]">⚠ {modelError}</span>
            )}
          </div>
          <div className="flex gap-2 items-center">
            <input
              type="text"
              value={cgSettings.directorLLM.model}
              onChange={e => onUpdate(prev => ({ ...prev, directorLLM: { ...prev.directorLLM, model: e.target.value } }))}
              placeholder="填写模型名或点击右侧刷新"
              className="flex-1 px-3.5 py-2 rounded-xl bg-[#edf1f4] border border-transparent text-[#1e242b] text-[12px] font-sans-m3 placeholder:text-[#84919e] focus:outline-none focus:bg-white focus:border-[#526070] transition-all"
            />
            <button
              type="button"
              onClick={() => {
                playSfx();
                handleFetchModels();
              }}
              disabled={isLoadingModels}
              title="拉取模型列表"
              className="flex items-center gap-1 px-3 py-2 rounded-xl bg-[#edf1f4] hover:bg-[#dde3e8] text-[#526070] text-[11px] font-sans-m3 font-semibold transition-all cursor-pointer disabled:opacity-40"
            >
              {isLoadingModels ? <Loader2 size={13} className="animate-spin" /> : <RefreshCw size={13} />}
              <span>拉取模型</span>
            </button>
          </div>

          {modelList.length > 0 && (
            <select
              value={cgSettings.directorLLM.model}
              onChange={e => {
                playSfx();
                onUpdate(prev => ({ ...prev, directorLLM: { ...prev.directorLLM, model: e.target.value } }));
              }}
              className="w-full px-3 py-1.5 rounded-lg bg-[#edf1f4] border border-transparent text-[#1e242b] text-[11.5px] font-sans-m3 focus:outline-none focus:bg-white focus:border-[#526070] transition-all cursor-pointer mt-1"
            >
              <option value="">-- 从拉取到的列表中快捷选取 --</option>
              {modelList.map(model => (
                <option key={model} value={model}>
                  {model}
                </option>
              ))}
            </select>
          )}
        </div>

        {/* 数量限制 */}
        <div className="grid grid-cols-2 gap-3 pt-1">
          <InputField
            label="单楼最少 CG 数量"
            type="number"
            placeholder="不限制"
            value={cgSettings.directorLLM.minCGCount !== undefined ? String(cgSettings.directorLLM.minCGCount) : ''}
            onChange={val => {
              const parsed = val === '' ? undefined : parseInt(val, 10);
              onUpdate(prev => ({ ...prev, directorLLM: { ...prev.directorLLM, minCGCount: parsed } }));
            }}
          />
          <InputField
            label="单楼最多 CG 数量"
            type="number"
            placeholder="不限制"
            value={cgSettings.directorLLM.maxCGCount !== undefined ? String(cgSettings.directorLLM.maxCGCount) : ''}
            onChange={val => {
              const parsed = val === '' ? undefined : parseInt(val, 10);
              onUpdate(prev => ({ ...prev, directorLLM: { ...prev.directorLLM, maxCGCount: parsed } }));
            }}
          />
        </div>

        <span className="font-sans-m3 text-[10px] text-[#84919e] -mt-1">
          留空表示不限制，由 AI 自行判断（默认 1~3 张）
        </span>

        {/* 提示词预设 */}
        <details className="flex flex-col gap-2 pt-2 border-t border-[#edf1f4]">
          <summary className="font-sans-m3 text-[11px] font-bold text-[#526070] cursor-pointer select-none">
            提示词预设 · 留空即用内置默认
          </summary>
          <div className="flex flex-col gap-3 mt-3">
            {(
              [
                { key: 'jailbreak', label: '破限词', hint: '置顶 system，降低副 API 对敏感剧情的拒答率' },
                { key: 'spec', label: '生图规范', hint: 'tags / char_caption / centers 的填写规则' },
                {
                  key: 'contract',
                  label: '任务协议',
                  hint: '数量、选段、输出格式与反注入；支持 {{countRule}} 与 {{coverage}} 占位符',
                },
                { key: 'thinking', label: '思维链', hint: '输出 JSON 前的检查清单，由任务协议强制模型输出' },
              ] as const
            ).map(field => (
              <div key={field.key} className="flex flex-col gap-1.5">
                <label className="font-sans-m3 text-[11px] font-semibold text-[#526070]">
                  {field.label}
                </label>
                <textarea
                  rows={4}
                  value={cgSettings.directorLLM.prompts?.[field.key] ?? ''}
                  placeholder="留空使用内置默认"
                  onChange={e => {
                    const val = e.target.value;
                    onUpdate(prev => ({
                      ...prev,
                      directorLLM: {
                        ...prev.directorLLM,
                        prompts: { ...prev.directorLLM.prompts, [field.key]: val },
                      },
                    }));
                  }}
                  className="w-full px-3 py-2 rounded-xl bg-[#edf1f4] border border-transparent text-[#1e242b] text-[11.5px] font-sans-m3 placeholder:text-[#84919e] focus:outline-none focus:bg-white focus:border-[#526070] transition-all resize-none"
                />
                <span className="font-sans-m3 text-[10px] text-[#84919e]">
                  {field.hint}
                </span>
              </div>
            ))}
          </div>
        </details>
      </div>

      {/* 缓存清理操作卡片 */}
      <div className="p-4 rounded-2xl bg-white border border-[#edf1f4] shadow-[0_2px_10px_rgba(30,36,43,0.03)] flex items-center justify-between gap-3">
        <div className="flex flex-col gap-0.5">
          <span className="font-sans-m3 text-[13px] font-bold text-[#1e242b]">
            CG 缓存数据管理
          </span>
          <span className="font-sans-m3 text-[10.5px] text-[#84919e]">
            清理已缓存到本地/服务器的图像资产，不影响配方
          </span>
        </div>
        <button
          type="button"
          onClick={() => {
            playSfx();
            onClearCache();
          }}
          disabled={isClearingCache}
          className="flex items-center gap-1.5 px-4 py-2 rounded-xl border border-[#c4384c]/20 bg-[#c4384c]/5 hover:bg-[#c4384c]/10 text-[#c4384c] text-[11.5px] font-sans-m3 font-semibold transition-all cursor-pointer disabled:opacity-40"
        >
          <Trash2 size={13} />
          <span>{isClearingCache ? '清理中...' : '清空全部 CG 缓存'}</span>
        </button>
      </div>
    </div>
  );
};

// ====== 角色库 Tab ======
const CharactersTab: React.FC<{
  charAppearances: Record<string, string>;
  isLoading: boolean;
  editingChar: { name: string; tags: string; isNew?: boolean } | null;
  onEdit: (char: { name: string; tags: string; isNew?: boolean } | null) => void;
  onSave: () => void;
  onDelete: (name: string) => void;
  onRefresh: () => void;
  playSfx: () => void;
}> = ({ charAppearances, isLoading, editingChar, onEdit, onSave, onDelete, onRefresh, playSfx }) => (
  <>
    <SectionHeader icon={<Database size={13} />} title="角色外貌库" subtitle="CHARACTER_APPEARANCES" />

    <div className="flex items-center justify-between">
      <span className="font-mono-retro text-[9px] text-[var(--color-cozy-muted)] tracking-[0.15em]">
        {isLoading ? '加载中...' : `${Object.keys(charAppearances).length} 个角色`}
      </span>
      <button
        onClick={() => {
          playSfx();
          onRefresh();
        }}
        disabled={isLoading}
        className="flex items-center gap-1 px-2 py-1 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro hover:text-[var(--color-cozy-ink)] hover:bg-[rgba(255,255,255,0.8)] transition-all duration-200 cursor-pointer disabled:opacity-50"
      >
        <RefreshCw size={10} className={isLoading ? 'animate-spin' : ''} />
        刷新
      </button>
    </div>

    {/* 添加新角色 */}
    {editingChar && editingChar.isNew ? (
      <div className="flex flex-col gap-2 p-3 rounded-xl bg-[rgba(255,255,255,0.3)] border border-[color:rgba(161,132,117,0.12)]">
        <input
          type="text"
          placeholder="角色名（如：白娅）"
          value={editingChar.name}
          onChange={e => onEdit({ name: e.target.value, tags: editingChar.tags, isNew: true })}
          autoFocus
          className="w-full px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 placeholder:text-[var(--color-cozy-muted)] placeholder:opacity-50 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200"
        />
        <textarea
          placeholder="外貌描述（Danbooru tags，如：1girl, white hair, blue eyes）"
          value={editingChar.tags}
          onChange={e => onEdit({ name: editingChar.name, tags: e.target.value, isNew: true })}
          rows={3}
          className="w-full px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[11px] font-sans-m3 placeholder:text-[var(--color-cozy-muted)] placeholder:opacity-50 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200 resize-none"
        />
        <div className="flex gap-2">
          <button
            onClick={onSave}
            className="flex-1 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[10px] font-mono-retro tracking-[0.15em] hover:shadow-[0_2px_8px_rgba(221,184,176,0.4)] transition-all duration-200 cursor-pointer"
          >
            保存
          </button>
          <button
            onClick={() => onEdit(null)}
            className="flex-1 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro tracking-[0.15em] hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
          >
            取消
          </button>
        </div>
      </div>
    ) : null}

    {/* 添加按钮 */}
    {!editingChar && (
      <button
        onClick={() => {
          playSfx();
          onEdit({ name: '', tags: '', isNew: true });
        }}
        className="flex items-center justify-center gap-1.5 py-2 rounded-xl border border-dashed border-[color:rgba(161,132,117,0.2)] bg-[rgba(255,255,255,0.2)] text-[var(--color-cozy-muted)] hover:text-[var(--color-cozy-ink)] hover:bg-[rgba(255,255,255,0.5)] transition-all duration-200 cursor-pointer"
      >
        <Plus size={12} />
        <span className="font-mono-retro text-[10px] tracking-[0.15em]">添加角色</span>
      </button>
    )}

    <div className="cozy-hairline h-px w-full opacity-60" />

    {/* 角色列表 */}
    <div className="flex flex-col gap-2 max-h-[260px] overflow-y-auto cozy-scrollbar">
      {Object.keys(charAppearances).length === 0 && !isLoading && (
        <div className="text-center py-4 text-[var(--color-cozy-muted)] font-mono-retro text-[10px] tracking-[0.15em]">
          暂无角色，点击上方按钮添加
        </div>
      )}
      {Object.entries(charAppearances).map(([name, tags]) => (
        <div
          key={name}
          className="flex items-start gap-2 px-3 py-2 rounded-xl bg-[rgba(255,255,255,0.3)] border border-[color:rgba(161,132,117,0.08)] hover:bg-[rgba(255,255,255,0.5)] transition-all duration-200"
        >
          <div className="flex-1 min-w-0">
            <div className="font-sans-m3 text-[13px] text-[#1e242b] font-bold mb-0.5">{name}</div>
            <div
              className="font-mono-retro text-[10px] text-[var(--color-cozy-muted)] tracking-[0.08em] truncate"
              title={tags}
            >
              {tags || '（无描述）'}
            </div>
          </div>
          <div className="flex gap-1 flex-shrink-0">
            <button
              onClick={() => {
                playSfx();
                onEdit({ name, tags });
              }}
              className="w-6 h-6 flex items-center justify-center rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
              title="编辑"
            >
              <Pencil size={10} />
            </button>
            <button
              onClick={() => onDelete(name)}
              className="w-6 h-6 flex items-center justify-center rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] hover:text-[#b86f6f] transition-all duration-200 cursor-pointer"
              title="删除"
            >
              <Trash2 size={10} />
            </button>
          </div>
        </div>
      ))}
    </div>

    {/* 编辑弹窗 */}
    {editingChar && !editingChar.isNew && (
      <div className="flex flex-col gap-2 p-3 rounded-xl bg-[rgba(255,255,255,0.3)] border border-[color:rgba(161,132,117,0.12)]">
        <div className="font-mono-retro text-[10px] text-[var(--color-cozy-muted)] tracking-[0.15em]">
          编辑: {editingChar.name}
        </div>
        <textarea
          value={editingChar.tags}
          onChange={e => onEdit({ ...editingChar, tags: e.target.value })}
          placeholder="外貌描述 tags，逗号分隔"
          rows={3}
          className="w-full px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[11px] font-sans-m3 placeholder:text-[var(--color-cozy-muted)] placeholder:opacity-50 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200 resize-none cozy-scrollbar"
        />
        <div className="flex gap-2">
          <button
            onClick={onSave}
            className="flex-1 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[10px] font-mono-retro tracking-[0.15em] hover:shadow-[0_2px_8px_rgba(221,184,176,0.4)] transition-all duration-200 cursor-pointer"
          >
            保存
          </button>
          <button
            onClick={() => onEdit(null)}
            className="flex-1 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro tracking-[0.15em] hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
          >
            取消
          </button>
        </div>
      </div>
    )}

    <span className="font-mono-retro text-[8px] text-[var(--color-cozy-muted)] tracking-[0.2em] opacity-50">
      数据来源: 世界书 [res]角色外貌库
    </span>
  </>
);

// ====== Vibe Tab ======
const VibeTab: React.FC<{
  schemes: VibeScheme[];
  activeSchemeId: string | null;
  onCreateScheme: (name: string) => void;
  onDeleteScheme: (id: string) => void;
  onRenameScheme: (id: string, name: string) => void;
  onSetActiveScheme: (id: string | null) => void;
  onUploadVibe: () => void;
  onRemoveVibe: (schemeId: string, vibeId: string) => void;
  onUpdateVibeParams: (schemeId: string, vibeId: string, params: { infoExtracted?: number; strength?: number }) => void;
  isUploading: boolean;
  /** 当前所选模型是否支持 Vibe */
  vibeSupported: boolean;
  /** 当前生效的出图方案名（仅用于显示归属） */
  activeProfileName?: string;
  playSfx: () => void;
}> = ({
  schemes,
  activeSchemeId,
  onCreateScheme,
  onDeleteScheme,
  onRenameScheme,
  onSetActiveScheme,
  onUploadVibe,
  onRemoveVibe,
  onUpdateVibeParams,
  isUploading,
  vibeSupported,
  activeProfileName,
  playSfx,
}) => {
  const [newSchemeName, setNewSchemeName] = useState('');
  const [editingSchemeId, setEditingSchemeId] = useState<string | null>(null);
  const [editingSchemeName, setEditingSchemeName] = useState('');

  const activeScheme = schemes.find(s => s.id === activeSchemeId);

  return (
    <>
      <SectionHeader icon={<Image size={13} />} title="Vibe 方案" subtitle="VIBE_TRANSFER" />

      {activeProfileName && (
        <span className="font-mono-retro text-[9px] text-[var(--color-cozy-muted)] tracking-[0.1em] -mt-2">
          当前出图方案：{activeProfileName}
        </span>
      )}

      {/* 当前模型不支持 Vibe 时的警告横幅 */}
      {!vibeSupported && (
        <div className="flex items-start gap-2 px-3 py-2 rounded-xl border border-[color:rgba(184,111,111,0.3)] bg-[rgba(184,111,111,0.08)]">
          <AlertTriangle size={13} className="text-[#b86f6f] flex-shrink-0 mt-0.5" />
          <span className="font-mono-retro text-[9px] text-[#b86f6f] tracking-[0.08em] leading-relaxed">
            当前模型不支持 Vibe 风格参考。已导入的方案会保留，但不会参与生成。
          </span>
        </div>
      )}

      {/* 方案选择下拉 */}
      <div className="flex items-center gap-2">
        <select
          value={activeSchemeId ?? ''}
          onChange={e => onSetActiveScheme(e.target.value || null)}
          className="flex-1 px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200 cursor-pointer"
        >
          <option value="">-- 选择方案 --</option>
          {schemes.map(s => (
            <option key={s.id} value={s.id}>
              {s.name} ({s.vibes.length} 个 Vibe)
            </option>
          ))}
        </select>
        {activeSchemeId && editingSchemeId !== activeSchemeId && (
          <button
            onClick={() => {
              playSfx();
              setEditingSchemeId(activeSchemeId);
              setEditingSchemeName(activeScheme?.name ?? '');
            }}
            className="w-7 h-7 flex items-center justify-center rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] hover:text-[var(--color-cozy-ink)] transition-all duration-200 cursor-pointer"
            title="重命名"
          >
            <Pencil size={10} />
          </button>
        )}
        {activeSchemeId && (
          <button
            onClick={() => onDeleteScheme(activeSchemeId)}
            className="w-7 h-7 flex items-center justify-center rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] hover:text-[#b86f6f] transition-all duration-200 cursor-pointer"
            title="删除方案"
          >
            <Trash2 size={10} />
          </button>
        )}
      </div>

      {/* 重命名输入 */}
      {editingSchemeId && editingSchemeId === activeSchemeId && (
        <div className="flex gap-2">
          <input
            type="text"
            value={editingSchemeName}
            onChange={e => setEditingSchemeName(e.target.value)}
            className="flex-1 px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200"
          />
          <button
            onClick={() => {
              if (editingSchemeName.trim()) {
                onRenameScheme(editingSchemeId, editingSchemeName.trim());
              }
              setEditingSchemeId(null);
            }}
            className="px-3 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[10px] font-mono-retro tracking-[0.15em] cursor-pointer"
          >
            确认
          </button>
          <button
            onClick={() => setEditingSchemeId(null)}
            className="px-3 py-1.5 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] text-[10px] font-mono-retro cursor-pointer"
          >
            取消
          </button>
        </div>
      )}

      {/* 新建方案 */}
      <div className="flex gap-2">
        <input
          type="text"
          value={newSchemeName}
          onChange={e => setNewSchemeName(e.target.value)}
          placeholder="新方案名称..."
          className="flex-1 px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 placeholder:text-[var(--color-cozy-muted)] placeholder:opacity-50 focus:outline-none focus:border-[var(--color-cozy-accent)] transition-all duration-200"
        />
        <button
          onClick={() => {
            if (newSchemeName.trim()) {
              playSfx();
              onCreateScheme(newSchemeName.trim());
              setNewSchemeName('');
            }
          }}
          className="px-3 py-1.5 rounded-lg bg-[var(--color-cozy-accent)] text-white text-[10px] font-mono-retro tracking-[0.15em] hover:shadow-[0_2px_8px_rgba(221,184,176,0.4)] transition-all duration-200 cursor-pointer"
        >
          <Plus size={12} />
        </button>
      </div>

      <div className="cozy-hairline h-px w-full opacity-60" />

      {/* 上传按钮：无方案时也能导入，导入会自动创建方案 */}
      <button
        onClick={onUploadVibe}
        disabled={isUploading}
        className="flex items-center justify-center gap-2 w-full py-2.5 rounded-xl border border-dashed border-[color:rgba(161,132,117,0.2)] bg-[rgba(255,255,255,0.2)] text-[var(--color-cozy-muted)] hover:text-[var(--color-cozy-ink)] hover:bg-[rgba(255,255,255,0.5)] transition-all duration-200 cursor-pointer disabled:opacity-50"
      >
        {isUploading ? <Loader2 size={14} className="animate-spin" /> : <Upload size={14} />}
        <span className="font-mono-retro text-[10px] tracking-[0.15em]">
          {isUploading ? '导入中...' : '导入 .naiv4vibebundle 方案'}
        </span>
      </button>

      {/* Vibe 列表 */}
      {!activeScheme ? (
        <div className="text-center py-4 text-[var(--color-cozy-muted)] font-mono-retro text-[10px] tracking-[0.15em] leading-relaxed">
          还没有 Vibe 方案
          <br />
          可直接导入 .naiv4vibebundle（会自动创建方案）
        </div>
      ) : (
        <div className="flex flex-col gap-3 max-h-[240px] overflow-y-auto cozy-scrollbar">
          {activeScheme.vibes.length === 0 ? (
            <div className="text-center py-4 text-[var(--color-cozy-muted)] font-mono-retro text-[10px] tracking-[0.15em]">
              暂无 Vibe，点击上方按钮导入
            </div>
          ) : (
            activeScheme.vibes.map(vibe => (
              <div
                key={vibe.id}
                className="flex items-center gap-3 px-3 py-2 rounded-xl bg-[rgba(255,255,255,0.3)] border border-[color:rgba(161,132,117,0.08)] hover:bg-[rgba(255,255,255,0.5)] transition-all duration-200"
              >
                {/* 缩略图：.naiv4vibebundle 不含参考图，用占位符 */}
                {vibe.imageBase64 ? (
                  <div
                    className="w-12 h-12 rounded-lg bg-cover bg-center flex-shrink-0 border border-[color:rgba(161,132,117,0.12)]"
                    style={{ backgroundImage: `url(${vibe.imageBase64})` }}
                  />
                ) : (
                  <div className="w-12 h-12 rounded-lg flex-shrink-0 border border-[color:rgba(161,132,117,0.12)] bg-[rgba(255,255,255,0.35)] flex items-center justify-center text-[var(--color-cozy-muted)] opacity-70">
                    <Image size={16} />
                  </div>
                )}
                <div className="flex-1 min-w-0">
                  <div
                    className="font-mono-retro text-[10px] text-[var(--color-cozy-ink)] tracking-[0.08em] truncate"
                    title={vibe.fileName}
                  >
                    {vibe.fileName}
                  </div>
                  <div className="flex gap-3 mt-1">
                    <div className="flex items-center gap-1">
                      <span className="font-mono-retro text-[8px] text-[var(--color-cozy-muted)]">提取</span>
                      <input
                        type="range"
                        min="0"
                        max="1"
                        step="0.05"
                        value={vibe.infoExtracted}
                        onChange={e =>
                          onUpdateVibeParams(activeSchemeId!, vibe.id, { infoExtracted: parseFloat(e.target.value) })
                        }
                        className="w-12 h-1 accent-[var(--color-cozy-accent)]"
                      />
                      <span className="font-mono-retro text-[8px] text-[var(--color-cozy-muted)]">
                        {vibe.infoExtracted.toFixed(2)}
                      </span>
                    </div>
                    <div className="flex items-center gap-1">
                      <span className="font-mono-retro text-[8px] text-[var(--color-cozy-muted)]">强度</span>
                      <input
                        type="range"
                        min="0"
                        max="1"
                        step="0.05"
                        value={vibe.strength}
                        onChange={e =>
                          onUpdateVibeParams(activeSchemeId!, vibe.id, { strength: parseFloat(e.target.value) })
                        }
                        className="w-12 h-1 accent-[var(--color-cozy-accent)]"
                      />
                      <span className="font-mono-retro text-[8px] text-[var(--color-cozy-muted)]">
                        {vibe.strength.toFixed(2)}
                      </span>
                    </div>
                  </div>
                </div>
                <button
                  onClick={() => onRemoveVibe(activeSchemeId!, vibe.id)}
                  className="w-6 h-6 flex items-center justify-center rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-muted)] hover:text-[#b86f6f] transition-all duration-200 cursor-pointer flex-shrink-0"
                  title="删除"
                >
                  <X size={10} />
                </button>
              </div>
            ))
          )}
        </div>
      )}
    </>
  );
};

// ====== 通用组件 ======

const SectionHeader: React.FC<{ icon: React.ReactNode; title: string; subtitle: string }> = ({
  icon,
  title,
  subtitle,
}) => (
  <div className="flex items-center gap-2 mt-1">
    <div className="text-[var(--color-cozy-accent)] opacity-80">{icon}</div>
    <span className="font-sans-m3 text-[13px] text-[#1e242b] font-bold">{title}</span>
    <span className="font-mono-retro text-[8px] text-[var(--color-cozy-muted)] tracking-[0.2em] uppercase">
      {subtitle}
    </span>
  </div>
);

const InputField: React.FC<{
  label: string;
  value: string;
  onChange: (val: string) => void;
  onBlur?: () => void;
  placeholder?: string;
  type?: string;
  className?: string;
}> = ({ label, value, onChange, onBlur, placeholder, type = 'text', className = '' }) => (
  <div className={`flex flex-col gap-1.5 ${className}`}>
    <label className="font-mono-retro text-[9px] text-[var(--color-cozy-muted)] tracking-[0.15em] uppercase">
      {label}
    </label>
    <input
      type={type}
      value={value}
      onChange={e => onChange(e.target.value)}
      onBlur={onBlur}
      placeholder={placeholder}
      className="w-full px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[12px] font-sans-m3 placeholder:text-[var(--color-cozy-muted)] placeholder:opacity-50 focus:outline-none focus:border-[var(--color-cozy-accent)] focus:shadow-[0_0_0_2px_rgba(221,184,176,0.2)] transition-all duration-200"
    />
  </div>
);

const TextAreaField: React.FC<{
  label: string;
  value: string;
  onChange: (val: string) => void;
  onBlur?: () => void;
  placeholder?: string;
}> = ({ label, value, onChange, onBlur, placeholder }) => (
  <div className="flex flex-col gap-1.5">
    <label className="font-mono-retro text-[9px] text-[var(--color-cozy-muted)] tracking-[0.15em] uppercase">
      {label}
    </label>
    <textarea
      value={value}
      onChange={e => onChange(e.target.value)}
      onBlur={onBlur}
      placeholder={placeholder}
      rows={3}
      className="w-full px-3 py-2 rounded-lg bg-[rgba(255,255,255,0.5)] border border-[color:rgba(161,132,117,0.15)] text-[var(--color-cozy-ink)] text-[11px] font-sans-m3 placeholder:text-[var(--color-cozy-muted)] placeholder:opacity-50 focus:outline-none focus:border-[var(--color-cozy-accent)] focus:shadow-[0_0_0_2px_rgba(221,184,176,0.2)] transition-all duration-200 resize-none cozy-scrollbar"
    />
  </div>
);

const ToggleSwitch: React.FC<{ checked: boolean; onChange: (checked: boolean) => void; disabled?: boolean }> = ({
  checked,
  onChange,
  disabled = false,
}) => (
  <button
    disabled={disabled}
    onClick={() => {
      if (!disabled) onChange(!checked);
    }}
    className={`relative w-10 h-5 rounded-full transition-all duration-300 ${
      disabled ? 'opacity-40 cursor-not-allowed' : 'cursor-pointer'
    } ${
      checked ? 'bg-[var(--color-cozy-accent)] shadow-[0_2px_8px_rgba(221,184,176,0.4)]' : 'bg-[rgba(161,132,117,0.2)]'
    }`}
  >
    <div
      className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-[0_1px_4px_rgba(0,0,0,0.15)] transition-all duration-300 ${
        checked ? 'left-[22px]' : 'left-0.5'
      }`}
    />
  </button>
);
