import React, { useState } from 'react';
import {
  AlertCircle,
  CheckCircle2,
  Database,
  Loader2,
  Plus,
  Trash2,
  Volume2,
  X,
} from './Icons';
import { checkMiniMaxAPIAvailable } from '../services/voiceService';
import { clearAllVoiceCache, getVoiceCacheStats } from '../services/voiceCacheDB';
import { notifyError, notifySuccess } from '../services/notify';
import type { VoiceConfig } from '../types';

interface VoiceConfigModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentConfig?: VoiceConfig;
  onSave: (config: VoiceConfig) => Promise<void>;
  playSfx: () => void;
}

export const VoiceConfigModal: React.FC<VoiceConfigModalProps> = ({
  isOpen,
  onClose,
  currentConfig,
  onSave,
  playSfx,
}) => {
  const [config, setConfig] = useState<VoiceConfig>(() => ({
    enabled: false,
    autoPlay: true,
    preloadEnabled: false,
    apiKey: '',
    model: 'speech-2.8-hd',
    characterVoices: {},
    ...currentConfig,
  }));

  const [newCharName, setNewCharName] = useState('');
  const [newVoiceUrl, setNewVoiceUrl] = useState('');
  const [isSaving, setIsSaving] = useState(false);
  const [isTestingConnection, setIsTestingConnection] = useState(false);
  const [connectionStatus, setConnectionStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [cacheStats, setCacheStats] = useState<{ count: number } | null>(null);
  const [isClearingCache, setIsClearingCache] = useState(false);

  React.useEffect(() => {
    if (currentConfig) {
      setConfig({
        ...currentConfig,
        enabled: currentConfig.enabled ?? false,
        autoPlay: currentConfig.autoPlay ?? true,
        preloadEnabled: currentConfig.preloadEnabled ?? false,
        apiKey: currentConfig.apiKey ?? '',
        model: currentConfig.model ?? 'speech-2.8-hd',
        characterVoices: currentConfig.characterVoices ?? {},
      });
    }
  }, [currentConfig]);

  const handleSave = async () => {
    playSfx();
    setIsSaving(true);
    try {
      await onSave(config);
      notifySuccess('语音配置已保存');
      onClose();
    } catch (e) {
      console.error('[VoiceConfigModal] 保存配置失败:', e);
      notifyError('保存配置失败，请检查控制台');
    } finally {
      setIsSaving(false);
    }
  };

  const handleAddCharacter = () => {
    const trimmedName = newCharName.trim();
    const trimmedVoice = newVoiceUrl.trim();
    if (!trimmedName) {
      notifyError('角色名不能为空');
      return;
    }
    if (!trimmedVoice) {
      notifyError('音色 ID 不能为空');
      return;
    }

    playSfx();
    setConfig({
      ...config,
      characterVoices: {
        ...config.characterVoices,
        [trimmedName]: {
          voice: trimmedVoice,
          volume: config.characterVoices[trimmedName]?.volume ?? 1.0,
        },
      },
    });
    setNewCharName('');
    setNewVoiceUrl('');
  };

  const handleDeleteCharacter = (name: string) => {
    playSfx();
    const newVoices = { ...config.characterVoices };
    delete newVoices[name];
    setConfig({ ...config, characterVoices: newVoices });
  };

  const handleUpdateVoiceUrl = (name: string, url: string) => {
    setConfig({
      ...config,
      characterVoices: {
        ...config.characterVoices,
        [name]: {
          ...config.characterVoices[name],
          voice: url,
        },
      },
    });
  };

  const loadCacheStats = async () => {
    const stats = await getVoiceCacheStats();
    setCacheStats(stats);
  };

  const handleClearCache = async () => {
    playSfx();
    setIsClearingCache(true);
    try {
      await clearAllVoiceCache();
      await loadCacheStats();
      notifySuccess('语音缓存已清空');
    } catch (e) {
      console.error('[VoiceConfigModal] 清理缓存失败:', e);
      notifyError('清理缓存失败，请检查控制台');
    } finally {
      setIsClearingCache(false);
    }
  };

  const handleTestConnection = async () => {
    const apiKey = config.apiKey?.trim();
    if (!apiKey) {
      notifyError('请先填写 API Key');
      return;
    }

    playSfx();
    setIsTestingConnection(true);
    setConnectionStatus('idle');
    try {
      const available = await checkMiniMaxAPIAvailable(apiKey);
      setConnectionStatus(available ? 'success' : 'error');
    } catch (e) {
      console.error('[VoiceConfigModal] 测试连接失败:', e);
      setConnectionStatus('error');
    } finally {
      setIsTestingConnection(false);
    }
  };

  React.useEffect(() => {
    if (isOpen) {
      loadCacheStats();
      setConnectionStatus('idle');
    }
  }, [isOpen]);

  if (!isOpen) return null;

  const charactersCount = Object.keys(config.characterVoices).length;

  return (
    <div className="game-modal fixed inset-0 z-[60] cozy-overlay flex items-center justify-center p-3 sm:p-5 animate-in fade-in duration-200">
      <div className="w-full max-w-4xl h-[92vh] max-h-[740px] min-h-[440px] rounded-[32px] bg-[#f7f9fa] border border-white shadow-[0_24px_64px_rgba(30,36,43,0.14)] relative overflow-hidden flex flex-col text-[#1e242b]">
        {/* Header */}
        <div className="flex justify-between items-center px-6 py-4 border-b border-[#edf1f4] bg-white/80 shrink-0">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 rounded-2xl bg-[#526070]/10 flex items-center justify-center text-[#526070]">
              <Volume2 size={18} />
            </div>
            <div className="flex flex-col">
              <h2 className="font-sans-m3 text-[16px] sm:text-[17px] text-[#1e242b] font-bold tracking-tight">
                语音引擎配置
              </h2>
              <span className="font-sans-m3 text-[10px] text-[#84919e]">
                MiniMax TTS 语音合成与角色音色绑定
              </span>
            </div>
          </div>
          <button
            onClick={() => {
              playSfx();
              onClose();
            }}
            className="w-8 h-8 flex items-center justify-center bg-[#edf1f4] hover:bg-[#dde3e8] rounded-full text-[#526070] hover:text-[#1e242b] transition-all cursor-pointer active:scale-95"
            onMouseEnter={playSfx}
          >
            <X size={15} />
          </button>
        </div>

        {/* Body - 双栏自适应网格 */}
        <div className="flex-1 grid grid-cols-1 min-[620px]:grid-cols-12 min-h-0 overflow-hidden divide-y min-[620px]:divide-y-0 min-[620px]:divide-x divide-[#edf1f4]">
          {/* 左栏：引擎总控、凭据与缓存 (42%) */}
          <div className="min-[620px]:col-span-5 p-5 overflow-y-auto cozy-scrollbar flex flex-col gap-4 bg-white/30">
            {/* 卡片 1：开关控制 */}
            <div className="p-4 rounded-2xl bg-white border border-white/80 shadow-[0_2px_10px_rgba(30,36,43,0.03)] flex flex-col gap-3">
              <div className="text-[11px] font-sans-m3 font-bold text-[#84919e] uppercase tracking-wider">
                全局开关
              </div>
              <div className="flex items-center justify-between gap-3">
                <div className="flex flex-col">
                  <span className="font-sans-m3 text-[13px] font-semibold text-[#1e242b]">启用语音</span>
                  <span className="text-[10px] text-[#84919e] font-sans-m3">
                    关闭后不自动播放、不预生成语音
                  </span>
                </div>
                <ToggleSwitch
                  checked={config.enabled}
                  onChange={checked => setConfig({ ...config, enabled: checked })}
                />
              </div>

              <div className="h-px w-full bg-[#edf1f4]" />

              <div className="flex items-center justify-between gap-3">
                <div className="flex flex-col">
                  <span className="font-sans-m3 text-[13px] font-semibold text-[#1e242b]">语音预加载</span>
                  <span className="text-[10px] text-[#84919e] font-sans-m3">
                    翻楼时提前生成当前楼层所有角色语音
                  </span>
                </div>
                <ToggleSwitch
                  checked={config.preloadEnabled ?? false}
                  onChange={checked => setConfig({ ...config, preloadEnabled: checked })}
                />
              </div>
            </div>

            {/* 卡片 2：API 凭据与测试 */}
            <div className="p-4 rounded-2xl bg-white border border-white/80 shadow-[0_2px_10px_rgba(30,36,43,0.03)] flex flex-col gap-3">
              <div className="flex items-center justify-between">
                <span className="text-[11px] font-sans-m3 font-bold text-[#84919e] uppercase tracking-wider">
                  MiniMax 凭据
                </span>
                <span className="text-[10px] font-sans-m3 text-[#526070] bg-[#edf1f4] px-2 py-0.5 rounded-full">
                  {config.model || 'speech-2.8-hd'}
                </span>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="font-sans-m3 text-[11px] font-semibold text-[#526070]">
                  API Key
                </label>
                <input
                  type="password"
                  value={config.apiKey}
                  onChange={e => {
                    setConfig({ ...config, apiKey: e.target.value });
                    setConnectionStatus('idle');
                  }}
                  placeholder="sk-..."
                  className="w-full px-3.5 py-2 rounded-xl bg-[#edf1f4] border border-transparent text-[#1e242b] text-[12.5px] font-sans-m3 placeholder:text-[#84919e] focus:outline-none focus:bg-white focus:border-[#526070] transition-all"
                />
              </div>

              {/* 连通性测试栏 */}
              <div className="flex items-center justify-between gap-2 pt-1">
                <span className="flex items-center gap-1.5 min-w-0 font-sans-m3 text-[11px]">
                  {connectionStatus === 'success' && (
                    <>
                      <CheckCircle2 size={13} className="shrink-0 text-[#6f9272]" />
                      <span className="text-[#6f9272] font-semibold truncate">Key 验证有效</span>
                    </>
                  )}
                  {connectionStatus === 'error' && (
                    <>
                      <AlertCircle size={13} className="shrink-0 text-[#c4384c]" />
                      <span className="text-[#c4384c] font-medium truncate">鉴权失败</span>
                    </>
                  )}
                  {connectionStatus === 'idle' && (
                    <span className="text-[#84919e] truncate">填写 Key 后测试连通性</span>
                  )}
                </span>
                <button
                  type="button"
                  onClick={handleTestConnection}
                  disabled={isTestingConnection || !config.apiKey?.trim()}
                  className="shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-full bg-[#edf1f4] hover:bg-[#dde3e8] text-[#526070] hover:text-[#1e242b] font-sans-m3 text-[11px] font-semibold transition-all cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
                >
                  {isTestingConnection ? (
                    <>
                      <Loader2 size={11} className="animate-spin" />
                      <span>测试中</span>
                    </>
                  ) : (
                    <span>测试连接</span>
                  )}
                </button>
              </div>
            </div>

            {/* 卡片 3：缓存管理 */}
            <div className="p-4 rounded-2xl bg-white border border-white/80 shadow-[0_2px_10px_rgba(30,36,43,0.03)] flex items-center justify-between gap-3">
              <div className="flex flex-col gap-0.5 min-w-0">
                <span className="font-sans-m3 text-[12px] font-bold text-[#1e242b]">
                  {cacheStats ? `${cacheStats.count} 条语音缓存` : '读取缓存中...'}
                </span>
                <span className="font-sans-m3 text-[10px] text-[#84919e] truncate">
                  存储于酒馆服务器，各端共享
                </span>
              </div>
              <button
                type="button"
                onClick={handleClearCache}
                disabled={isClearingCache || !cacheStats || cacheStats.count === 0}
                className="shrink-0 flex items-center gap-1.5 px-3 py-1.5 rounded-xl border border-[#c4384c]/20 bg-[#c4384c]/5 hover:bg-[#c4384c]/10 text-[#c4384c] text-[11px] font-sans-m3 font-semibold transition-all cursor-pointer disabled:opacity-40 disabled:cursor-not-allowed"
              >
                <Trash2 size={12} />
                <span>{isClearingCache ? '清理中' : '清空'}</span>
              </button>
            </div>
          </div>

          {/* 右栏：角色音色映射专区 (58%) */}
          <div className="min-[620px]:col-span-7 p-5 flex flex-col gap-4 min-h-0 bg-white/60">
            {/* 顶栏：统计与快速添加区 */}
            <div className="p-4 rounded-2xl bg-white border border-[#edf1f4] shadow-[0_2px_10px_rgba(30,36,43,0.03)] flex flex-col gap-2.5">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Database size={14} className="text-[#526070]" />
                  <span className="font-sans-m3 text-[13px] font-bold text-[#1e242b]">
                    添加角色音色绑定
                  </span>
                </div>
                <span className="text-[11px] font-sans-m3 font-medium text-[#84919e]">
                  已绑 {charactersCount} 个角色
                </span>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                <input
                  type="text"
                  value={newCharName}
                  onChange={e => setNewCharName(e.target.value)}
                  placeholder="角色名（如: 艾莉丝）"
                  className="w-full px-3 py-2 rounded-xl bg-[#edf1f4] border border-transparent text-[#1e242b] text-[12px] font-sans-m3 placeholder:text-[#84919e] focus:outline-none focus:bg-white focus:border-[#526070] transition-all"
                />
                <input
                  type="text"
                  value={newVoiceUrl}
                  onChange={e => setNewVoiceUrl(e.target.value)}
                  placeholder="音色 ID (voice_id)"
                  className="w-full px-3 py-2 rounded-xl bg-[#edf1f4] border border-transparent text-[#1e242b] text-[12px] font-sans-m3 placeholder:text-[#84919e] focus:outline-none focus:bg-white focus:border-[#526070] transition-all"
                />
              </div>

              <button
                type="button"
                onClick={handleAddCharacter}
                className="self-end flex items-center gap-1.5 px-4 py-1.5 rounded-xl bg-[#526070] hover:bg-[#3d4855] text-white text-[11.5px] font-sans-m3 font-semibold transition-all cursor-pointer shadow-sm active:scale-95"
              >
                <Plus size={13} />
                <span>添加绑定</span>
              </button>
            </div>

            {/* 角色卡片列表（独立滚动） */}
            <div className="flex-1 overflow-y-auto cozy-scrollbar flex flex-col gap-2.5 pr-1 min-h-[160px]">
              {charactersCount === 0 ? (
                <div className="flex-1 flex flex-col items-center justify-center py-10 text-[#84919e] font-sans-m3 text-[12px] border border-dashed border-[#edf1f4] rounded-2xl bg-white/40">
                  <Volume2 size={24} className="opacity-30 mb-2" />
                  <span>暂无角色音色，请在上方添加</span>
                </div>
              ) : (
                Object.entries(config.characterVoices).map(([name, voice]) => (
                  <div
                    key={name}
                    className="p-3.5 rounded-2xl bg-white border border-[#edf1f4] hover:border-[#526070]/30 shadow-[0_2px_8px_rgba(30,36,43,0.03)] transition-all flex flex-col gap-2"
                  >
                    <div className="flex items-center justify-between">
                      <span className="font-sans-m3 text-[13.5px] text-[#1e242b] font-bold tracking-tight">
                        {name}
                      </span>
                      <button
                        type="button"
                        onClick={() => handleDeleteCharacter(name)}
                        className="w-7 h-7 flex items-center justify-center rounded-lg bg-[#edf1f4] hover:bg-[#c4384c]/10 text-[#84919e] hover:text-[#c4384c] transition-all cursor-pointer"
                        title="删除角色"
                      >
                        <Trash2 size={12} />
                      </button>
                    </div>

                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-sans-m3 font-semibold text-[#84919e] shrink-0">
                        voice_id
                      </span>
                      <input
                        type="text"
                        value={voice.voice || ''}
                        onChange={e => handleUpdateVoiceUrl(name, e.target.value)}
                        placeholder="填入音色 ID"
                        className="flex-1 px-3 py-1.5 rounded-lg bg-[#edf1f4] border border-transparent text-[#1e242b] text-[11.5px] font-sans-m3 focus:outline-none focus:bg-white focus:border-[#526070] transition-all"
                      />
                    </div>
                  </div>
                ))
              )}
            </div>

            <span className="font-sans-m3 text-[10px] text-[#84919e] shrink-0">
              角色名需与对话文本中的 [char:角色名] 一致；配方存入世界书 [res]角色语音。
            </span>
          </div>
        </div>

        {/* Footer */}
        <div className="px-6 py-3.5 border-t border-[#edf1f4] bg-white flex justify-between items-center shrink-0">
          <span className="text-[11px] font-sans-m3 text-[#84919e]">
            已加载配置项 · MiniMax Speech 引擎
          </span>
          <div className="flex items-center gap-2.5">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 rounded-xl bg-[#edf1f4] hover:bg-[#dde3e8] text-[#526070] text-[12px] font-sans-m3 font-semibold transition-all cursor-pointer"
            >
              取消
            </button>
            <button
              type="button"
              onClick={handleSave}
              disabled={isSaving}
              className="flex items-center gap-1.5 px-5 py-2 rounded-xl bg-[#526070] hover:bg-[#3d4855] text-white text-[12px] font-sans-m3 font-semibold shadow-sm transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed active:scale-95"
            >
              {isSaving ? (
                <>
                  <Loader2 size={13} className="animate-spin" />
                  <span>保存中...</span>
                </>
              ) : (
                <span>保存并应用</span>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

const ToggleSwitch: React.FC<{ checked: boolean; onChange: (checked: boolean) => void }> = ({
  checked,
  onChange,
}) => (
  <button
    type="button"
    onClick={() => onChange(!checked)}
    className={`relative w-10 h-5 rounded-full transition-colors duration-200 cursor-pointer shrink-0 ${
      checked ? 'bg-[#526070]' : 'bg-[#dde3e8]'
    }`}
  >
    <div
      className={`absolute top-0.5 w-4 h-4 rounded-full bg-white shadow-sm transition-all duration-200 ${
        checked ? 'left-5.5' : 'left-0.5'
      }`}
    />
  </button>
);
