/**
 * Voice Service - 调用 MiniMax 国内站同步语音合成 HTTP（speech-2.8-hd）实现角色语音播报
 * 官方文档：https://platform.minimax.cn/document/apis/speech/t2a_v2
 */

import type { CharacterVoiceSettings, VoiceConfig } from '../types';
import { MINIMAX_BASE_URL, MINIMAX_DEFAULT_MODEL } from '../constants';
import { getVoiceAudio, putVoiceAudio } from './voiceCacheDB';

/** 当前播放的音频实例（用于停止） */
let currentAudio: HTMLAudioElement | null = null;

/** 所有活跃的音频实例列表（用于清理） */
const activeAudios = new Set<HTMLAudioElement>();

/** 当前播放请求的唯一ID */
let currentPlayId = 0;

/** 当前语音合成请求的 AbortController（用于实时播放的单个请求） */
let currentAbortController: AbortController | null = null;

/** 内存缓存（文本+音色 → Blob），避免同一会话重复合成，页面刷新后清空 */
const memoryCache = new Map<string, Blob>();

/** 内存缓存条目上限，超出按 FIFO 逐出，避免长会话内存无限增长 */
const MEMORY_CACHE_MAX = 200;

function cacheMemoryBlob(key: string, blob: Blob): void {
  if (!memoryCache.has(key) && memoryCache.size >= MEMORY_CACHE_MAX) {
    const oldest = memoryCache.keys().next().value;
    if (oldest !== undefined) memoryCache.delete(oldest);
  }
  memoryCache.set(key, blob);
}

/** 临时语音缓存（用于 roll 未保存的语音），不写入持久化缓存 */
const tempVoiceCache = new Map<string, Blob>();

/** 请求队列任务 */
interface QueueTask {
  id: number;
  execute: () => Promise<any>;
  resolve: (value: any) => void;
  reject: (error: any) => void;
  isRealtime: boolean;
  abortController?: AbortController;
}

/** 请求队列 */
let requestQueue: QueueTask[] = [];
let isProcessingQueue = false;
let nextTaskId = 0;
/** 当前正在执行的任务 */
let currentExecutingTask: QueueTask | null = null;

/** 预加载取消标志：置位后 preloadService 的语音阶段应尽快停止 */
let preloadCancelled = false;

/** 处理请求队列（确保同一时间只有一个请求在执行） */
async function processQueue(): Promise<void> {
  if (isProcessingQueue || requestQueue.length === 0) {
    return;
  }

  isProcessingQueue = true;

  while (requestQueue.length > 0) {
    const task = requestQueue.shift()!;
    currentExecutingTask = task;

    try {
      const result = await task.execute();
      task.resolve(result);
    } catch (error) {
      task.reject(error);
    } finally {
      currentExecutingTask = null;
    }
  }

  isProcessingQueue = false;
}

/** 将请求加入队列 */
function enqueueRequest<T>(execute: (abortController: AbortController) => Promise<T>, isRealtime: boolean): Promise<T> {
  return new Promise((resolve, reject) => {
    const taskId = nextTaskId++;
    const abortController = new AbortController();

    const task: QueueTask = {
      id: taskId,
      execute: () => execute(abortController),
      resolve,
      reject,
      isRealtime,
      abortController,
    };

    // 实时播放请求插入队列前面（优先处理），预加载请求排在后面
    if (isRealtime) {
      // 找到第一个非实时任务的位置
      const firstPreloadIndex = requestQueue.findIndex(t => !t.isRealtime);
      if (firstPreloadIndex === -1) {
        requestQueue.push(task);
      } else {
        requestQueue.splice(firstPreloadIndex, 0, task);
      }
    } else {
      requestQueue.push(task);
    }

    processQueue();
  });
}

/** 解析模型名：空值或遗留的 MiMo 模型一律回退到 MiniMax 默认模型 */
function resolveModel(model?: string): string {
  const resolved = (model || '').trim();
  if (!resolved || resolved.startsWith('mimo')) {
    return MINIMAX_DEFAULT_MODEL;
  }
  return resolved;
}

/** 生成语音缓存键（含模型与音色前缀，避免切换模型后命中旧缓存） */
function makeVoiceCacheKey(model: string, text: string, voice: string): string {
  return `${resolveModel(model)}:${voice}:${text.slice(0, 200)}`;
}

/**
 * 发送给 MiniMax 前的文本清洗：移除内心独白标记、富文本标签、换行符。
 * 清洗结果会直接进入缓存键，因此全库必须共用这一份实现——任何一处口径不一致
 * 都会导致同一句重复合成、重复计费，且难以察觉。
 */
function cleanTextForTTS(text: string): string {
  return text
    .replace(/\[inner\]/g, '')
    .replace(/[()（）]/g, '')
    .replace(/<[^>]+>/g, '')
    .replace(/\n/g, ' ')
    .trim();
}

/**
 * 解析 voice 配置
 * MiniMax 只接受 voice_id 字符串（系统音色 ID 或「快速复刻」得到的 voice_id），
 * 不再支持音频 URL / Base64。
 *
 * @param voice 原始 voice 配置（voice_id）
 * @returns 去除首尾空白后的 voice_id
 */
async function resolveVoiceConfig(voice: string): Promise<string> {
  const resolved = (voice || '').trim();

  // 兼容旧配置：历史数据里可能是音频 URL 或 Base64，MiniMax 无法使用，给出明确提示
  if (resolved.startsWith('data:audio/') || resolved.startsWith('http://') || resolved.startsWith('https://')) {
    console.warn(
      '[voiceService] 音色配置仍是旧的 URL/Base64 格式，MiniMax 只接受 voice_id，请在「语音配置」中改为 voice_id',
    );
  }

  return resolved;
}

/**
 * 将 hex 字符串解析为字节数组
 * MiniMax 非流式返回的 `data.audio` 为 hex 编码音频
 */
function hexToBytes(hex: string) {
  const clean = hex.trim();
  const length = Math.floor(clean.length / 2);
  const bytes = new Uint8Array(length);
  for (let i = 0; i < length; i++) {
    bytes[i] = parseInt(clean.substr(i * 2, 2), 16);
  }
  return bytes;
}

/**
 * 调用 MiniMax 国内站同步语音合成 HTTP 合成语音
 * @param text 要合成的文本
 * @param voiceSettings 角色语音设置（voice 为 voice_id）
 * @param config 全局语音配置
 * @param externalAbortController 外部传入的 AbortController（用于取消）
 * @param isRealtime 是否是实时播放（实时播放减少重试次数，避免干扰用户）
 * @returns 音频 Blob (MP3 格式)
 */
async function synthesizeVoiceWithMiniMax(
  text: string,
  voiceSettings: CharacterVoiceSettings,
  config: VoiceConfig,
  externalAbortController: AbortController,
  isRealtime: boolean = false,
): Promise<Blob> {
  // 使用传入的 AbortController
  const abortController = externalAbortController;

  // 限流重试逻辑
  const RETRY_DELAY = 3000;
  // 实时播放时减少重试次数，避免长时间卡顿
  const MAX_RETRY_COUNT = isRealtime ? 2 : 10;
  let retryCount = 0;

  try {
    // 构建请求体（MiniMax T2A v2 非流式）
    const requestBody: any = {
      model: resolveModel(config.model),
      text,
      stream: false,
      voice_setting: {
        voice_id: voiceSettings.voice,
        speed: 1,
        vol: 1,
        pitch: 0,
      },
      audio_setting: {
        format: 'mp3',
        sample_rate: 32000,
        channel: 1,
      },
      language_boost: 'auto',
      output_format: 'hex',
    };

    while (true) {
      // 检查取消信号
      if (abortController.signal.aborted) {
        throw new Error('请求已取消');
      }

      try {
        // 创建一个带超时的 AbortController (60秒超时，hd 模型延迟更高)
        const timeoutId = setTimeout(() => {
          console.error('[voiceService] 请求超时 (60秒)');
          abortController.abort('timeout');
        }, 60000);

        const response = await fetch(`${MINIMAX_BASE_URL}/v1/t2a_v2`, {
          method: 'POST',
          headers: {
            Authorization: `Bearer ${config.apiKey}`,
            'Content-Type': 'application/json',
          },
          body: JSON.stringify(requestBody),
          signal: abortController.signal,
        }).finally(() => clearTimeout(timeoutId));

        // HTTP 层错误（HTTP 200 也可能带业务错误，因此这里只处理非 2xx）
        if (!response.ok) {
          const errorText = await response.text().catch(() => '');
          console.error('[voiceService] 请求失败:', {
            status: response.status,
            statusText: response.statusText,
            errorBody: errorText.slice(0, 500),
          });

          // HTTP 429：自动重试
          if (response.status === 429) {
            retryCount++;

            if (retryCount >= MAX_RETRY_COUNT) {
              throw new Error(`MiniMax API 速率限制 (429 rate limit)，已重试 ${retryCount} 次，请稍后再试`);
            }

            await new Promise(resolve => setTimeout(resolve, RETRY_DELAY));
            continue;
          }

          // 其他 HTTP 错误直接抛出
          throw new Error(`MiniMax API 返回错误 ${response.status}: ${errorText}`);
        }

        const result = await response.json().catch(() => null);

        // HTTP 200 也可能带业务错误，错误码放在 base_resp 中（data 可能为 null）
        const baseResp = result?.data?.base_resp ?? result?.base_resp;
        const statusCode: number | undefined = baseResp?.status_code;
        const statusMsg: string = baseResp?.status_msg || '未知错误';

        // 限流：1002 限流 / 1039 TPM 限流 → 重试（消息中保留 429 / rate limit 供上层退避识别）
        if (statusCode === 1002 || statusCode === 1039) {
          retryCount++;

          if (retryCount >= MAX_RETRY_COUNT) {
            throw new Error(
              `MiniMax API 速率限制 (429 rate limit, code ${statusCode}: ${statusMsg})，已重试 ${retryCount} 次，请稍后再试`,
            );
          }

          await new Promise(resolve => setTimeout(resolve, RETRY_DELAY));
          continue;
        }

        // 其他业务错误码
        if (statusCode !== undefined && statusCode !== 0) {
          console.error('[voiceService] MiniMax 业务错误:', { statusCode, statusMsg });

          switch (statusCode) {
            case 1004:
              throw new Error(
                `MiniMax API 鉴权失败 (code 1004: ${statusMsg})，请检查 API Key 是否来自国内站 platform.minimax.cn`,
              );
            case 1042:
              throw new Error(`MiniMax API 文本包含非法字符 (code 1042: ${statusMsg})，请调整台词内容`);
            case 2013:
              throw new Error(`MiniMax API 参数错误 (code 2013: ${statusMsg})，请检查模型与音色配置`);
            default:
              throw new Error(`MiniMax API 返回错误 (code ${statusCode}: ${statusMsg})`);
          }
        }

        if (!result?.data) {
          throw new Error(`MiniMax API 返回数据异常: ${statusMsg}`);
        }

        // 解析返回的 hex 音频数据
        const audioHex = result.data.audio;
        if (!audioHex || typeof audioHex !== 'string') {
          throw new Error('MiniMax API 返回中未找到音频数据');
        }

        const bytes = hexToBytes(audioHex);
        if (bytes.length === 0) {
          throw new Error('MiniMax API 返回的音频数据为空');
        }

        return new Blob([bytes], { type: 'audio/mpeg' });
      } catch (error) {
        // 如果是取消错误，直接抛出
        if (error instanceof Error && (error.name === 'AbortError' || abortController.signal.aborted)) {
          throw new Error('请求已取消');
        }

        // 其他错误直接抛出，不再重试
        throw error;
      }
    }
  } finally {
    // 清理完成
  }
}

/**
 * 播放语音音频
 * @param audioBlob 音频 Blob
 * @param volume 音量 0.0-1.0
 * @param playId 本次播放的唯一ID
 * @returns Promise，播放完成时 resolve
 */
function playVoiceAudio(audioBlob: Blob, volume: number, playId: number): Promise<void> {
  return new Promise(resolve => {
    // 检查是否已经是过期的播放请求
    if (playId !== currentPlayId) {
      resolve();
      return;
    }

    const audioUrl = URL.createObjectURL(audioBlob);
    const audio = document.createElement('audio');
    audio.src = audioUrl;
    audio.volume = Math.max(0, Math.min(1, volume));

    // 加入活跃音频列表
    activeAudios.add(audio);

    // 设置为当前音频
    currentAudio = audio;

    const cleanup = () => {
      activeAudios.delete(audio);
      URL.revokeObjectURL(audioUrl);
      if (currentAudio === audio) {
        currentAudio = null;
      }
    };

    audio.onended = () => {
      cleanup();
      resolve();
    };

    audio.onerror = () => {
      cleanup();
      resolve(); // 不 reject，被中断是正常的
    };

    // 尝试播放，但在播放前再次检查ID
    if (playId !== currentPlayId) {
      cleanup();
      resolve();
      return;
    }

    audio
      .play()
      .then(() => {
        // play() 成功后立即检查ID，如果已过期立即停止
        if (playId !== currentPlayId) {
          try {
            audio.pause();
            audio.currentTime = 0;
            audio.src = '';
            audio.load(); // 强制重置
          } catch (e) {
            // 忽略错误
          }
          cleanup();
          resolve();
          return;
        }

        // 添加定期检查机制，每50ms检查一次playId是否还有效
        const checkInterval = setInterval(() => {
          if (playId !== currentPlayId) {
            clearInterval(checkInterval);
            try {
              audio.pause();
              audio.currentTime = 0;
              audio.src = '';
              audio.load();
            } catch (e) {
              // 忽略错误
            }
            cleanup();
            resolve();
          }
        }, 50);

        // 音频结束时清除定时器
        const originalOnended = audio.onended;
        audio.onended = ev => {
          clearInterval(checkInterval);
          if (originalOnended) {
            originalOnended.call(audio, ev);
          }
        };

        const originalOnerror = audio.onerror;
        audio.onerror = e => {
          clearInterval(checkInterval);
          if (originalOnerror) {
            originalOnerror.call(audio, e);
          }
        };
      })
      .catch(() => {
        // 播放失败也清理
        cleanup();
        resolve();
      });
  });
}

/**
 * 停止当前正在播放的语音
 */
export function stopCurrentVoice(): void {
  // 中止当前的合成请求
  if (currentAbortController) {
    currentAbortController.abort();
    currentAbortController = null;
  }

  // 停止并清理所有活跃的音频元素
  if (activeAudios.size > 0) {
    const audiosToClean = Array.from(activeAudios);
    activeAudios.clear(); // 先清空集合，防止在清理过程中被修改

    audiosToClean.forEach(audio => {
      try {
        // 移除所有事件监听器，防止触发回调
        audio.onended = null;
        audio.onerror = null;
        audio.onpause = null;
        audio.onplay = null;

        // 立即暂停
        audio.pause();

        // 清空 src 并重置
        const currentSrc = audio.src;
        audio.src = '';
        audio.load();

        // 释放 Blob URL
        if (currentSrc && currentSrc.startsWith('blob:')) {
          URL.revokeObjectURL(currentSrc);
        }
      } catch (e) {
        // 忽略错误
      }
    });
  }

  // 清除当前音频引用
  currentAudio = null;
}

/**
 * 取消所有预加载任务（清空队列中的预加载任务，并中止正在执行的预加载任务）
 */
export function cancelPreloadVoice(): void {
  // 0. 置位取消标志，让 preloadService 的语音循环尽快停止
  preloadCancelled = true;

  // 1. 中止正在执行的预加载任务
  if (currentExecutingTask && !currentExecutingTask.isRealtime) {
    currentExecutingTask.abortController?.abort();
  }

  // 2. 清空队列中的预加载任务
  requestQueue = requestQueue.filter(t => t.isRealtime);
}

/**
 * 是否已请求取消语音预加载（由 preloadService 在每句前检查）
 */
export function isPreloadCancelled(): boolean {
  return preloadCancelled;
}

/**
 * 重置语音预加载状态（由 preloadService 在每次 startPreload 时调用）
 */
export function resetPreloadVoice(): void {
  preloadCancelled = false;
}

/**
 * 合成并播放语音（一体化接口）
 * @param text 要合成的文本
 * @param voiceSettings 角色语音设置
 * @param config 全局语音配置
 * @param globalVolume 全局音量
 * @returns Promise，播放完成时 resolve
 */
/**
 * 合成并播放语音（自动播放用）
 * @param allowGenerate 是否允许在无缓存时自动生成。自动播放传 false——
 *   只播放已生成的语音，不自动生成；生成交给「预加载」或手动「生成」。
 */
export async function synthesizeAndPlayVoice(
  text: string,
  voiceSettings: CharacterVoiceSettings,
  config: VoiceConfig,
  globalVolume: number = 1.0,
  allowGenerate: boolean = true,
): Promise<void> {
  try {
    // 立即停止之前的所有语音操作，并生成新的播放ID
    stopCurrentVoice();
    currentPlayId++;
    const thisPlayId = currentPlayId;

    // 清理文本：移除内心独白标记、富文本标签、换行符
    const textForTTS = cleanTextForTTS(text);

    if (!textForTTS) {
      return;
    }

    // 创建新的 AbortController 用于这次请求
    currentAbortController = new AbortController();
    const thisAbortController = currentAbortController;

    // 解析 voice 配置（自动处理 URL、Base64、预置音色）
    const resolvedVoice = await resolveVoiceConfig(voiceSettings.voice);

    // 解析配置后立即检查播放ID
    if (thisPlayId !== currentPlayId) {
      return;
    }

    const resolvedSettings = { ...voiceSettings, voice: resolvedVoice };

    // 生成缓存键（含模型与音色，避免切换后命中旧缓存）
    const cacheKey = makeVoiceCacheKey(config.model, textForTTS, resolvedVoice);

    // 检查播放ID是否还有效
    if (thisPlayId !== currentPlayId) {
      return;
    }

    // 检查是否被中止
    if (thisAbortController.signal.aborted) {
      return;
    }

    // 1. 先检查内存缓存（最快）
    let audioBlob: Blob | undefined = memoryCache.get(cacheKey);

    // 2. 如果内存缓存没有，检查 IndexedDB 持久化缓存
    if (!audioBlob) {
      const cachedBlob = await getVoiceAudio(cacheKey);
      if (cachedBlob) {
        audioBlob = cachedBlob;
        // 写回内存缓存
        cacheMemoryBlob(cacheKey, cachedBlob);
      }
    }

    // 再次检查播放ID
    if (thisPlayId !== currentPlayId) {
      return;
    }

    // 再次检查是否被中止
    if (thisAbortController.signal.aborted) {
      return;
    }

    // 3. 如果都没有缓存：只有允许自动生成时才调用 API
    if (!audioBlob) {
      if (!allowGenerate) {
        // 自动播放：只播放已生成的语音，不自动生成（避免读到哪就已经偷偷生成好）
        return;
      }
      audioBlob = await synthesizeVoiceWithMiniMax(textForTTS, resolvedSettings, config, thisAbortController, true);

      // 同时写入内存缓存和 IndexedDB
      cacheMemoryBlob(cacheKey, audioBlob);
      putVoiceAudio(cacheKey, audioBlob).catch(err => {
        console.error('[voiceService] 写入 IndexedDB 失败:', err);
      });
    }

    // 最后一次检查播放ID
    if (thisPlayId !== currentPlayId) {
      return;
    }

    // 最后一次检查是否被中止
    if (thisAbortController.signal.aborted) {
      return;
    }

    // 计算最终音量：角色音量 × 全局音量
    const finalVolume = voiceSettings.volume * globalVolume;
    await playVoiceAudio(audioBlob, finalVolume, thisPlayId);

    // 播放完成后，清除 AbortController
    if (currentAbortController === thisAbortController) {
      currentAbortController = null;
    }
  } catch (error) {
    // 如果是用户取消（AbortError），不报错
    if (error instanceof Error && (error.name === 'AbortError' || error.message.includes('已取消'))) {
      return;
    }
    console.error('[voiceService] 语音合成或播放失败:', error);
    throw error;
  }
}

/**
 * 预生成语音（不播放，仅缓存）
 * @param text 要合成的文本
 * @param voiceSettings 角色语音设置
 * @param config 全局语音配置
 * @returns Promise<boolean>，true 表示使用了缓存，false 表示新生成
 */
export async function synthesizeAndPreloadVoice(
  text: string,
  voiceSettings: CharacterVoiceSettings,
  config: VoiceConfig,
): Promise<boolean> {
  try {
    // 清理文本
    const cleanText = cleanTextForTTS(text);

    if (!cleanText) {
      return true; // 空文本视为已缓存
    }

    // 解析 voice 配置
    const resolvedVoice = await resolveVoiceConfig(voiceSettings.voice);
    const resolvedSettings = { ...voiceSettings, voice: resolvedVoice };

    // 生成缓存键
    const cacheKey = makeVoiceCacheKey(config.model, cleanText, resolvedVoice);

    // 1. 检查内存缓存
    if (memoryCache.has(cacheKey)) {
      return true; // 使用了缓存
    }

    // 2. 检查 IndexedDB 缓存
    const cachedBlob = await getVoiceAudio(cacheKey);
    if (cachedBlob) {
      // 写回内存缓存
      cacheMemoryBlob(cacheKey, cachedBlob);
      return true; // 使用了缓存
    }

    // 3. 通过队列执行合成请求（预加载，低优先级）
    const audioBlob = await enqueueRequest(
      abortController => synthesizeVoiceWithMiniMax(cleanText, resolvedSettings, config, abortController, false),
      false, // isRealtime
    );

    // 同时写入内存缓存和 IndexedDB
    cacheMemoryBlob(cacheKey, audioBlob);
    putVoiceAudio(cacheKey, audioBlob).catch(err => {
      console.error('[voiceService] 预加载写入 IndexedDB 失败:', err);
    });

    return false; // 新生成
  } catch (error) {
    if (error instanceof Error && (error.name === 'AbortError' || error.message.includes('已取消'))) {
      return false;
    }
    console.error('[voiceService] 语音预生成失败:', error);
    throw error;
  }
}

/**
 * 检查 MiniMax API Key 是否可用（验证密钥）
 * 使用不计费的音色列表接口，避免为了验证密钥而合成一次音频。
 * 注意：MiniMax 鉴权失败时仍返回 HTTP 200，必须再检查 base_resp.status_code。
 * @param apiKey API 密钥
 * @returns 是否可用
 */
export async function checkMiniMaxAPIAvailable(apiKey: string): Promise<boolean> {
  try {
    const response = await fetch(`${MINIMAX_BASE_URL}/v1/get_voice`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${apiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ voice_type: 'all' }),
      signal: AbortSignal.timeout(15000),
    });

    if (!response.ok) {
      return false;
    }

    const result = await response.json().catch(() => null);
    const statusCode = result?.data?.base_resp?.status_code ?? result?.base_resp?.status_code;
    if (statusCode !== undefined) {
      return statusCode === 0;
    }

    // 响应结构异常时（无 base_resp），回退到「是否拿到音色列表」判断
    return !!result;
  } catch {
    return false;
  }
}

/**
 * 设置预加载状态（由 preloadService 调用）
 *
 * 语音服务当前不消费该状态，保留空实现仅为兼容既有调用点。
 */
export function setPreloadingState(_state: boolean): void {}

/**
 * 重新生成语音（不保存到缓存，存入临时缓存）
 * @param text 要合成的文本
 * @param voiceSettings 角色语音设置
 * @param config 全局语音配置
 * @returns 新生成的音频 Blob
 */
export async function regenerateVoice(
  text: string,
  voiceSettings: CharacterVoiceSettings,
  config: VoiceConfig,
): Promise<Blob> {
  // 清理文本
  const textForTTS = cleanTextForTTS(text);

  if (!textForTTS) {
    throw new Error('清理后文本为空');
  }

  // 解析 voice 配置
  const resolvedVoice = await resolveVoiceConfig(voiceSettings.voice);
  const resolvedSettings = { ...voiceSettings, voice: resolvedVoice };

  // 调用 API 重新生成（不检查缓存）
  const audioBlob = await synthesizeVoiceWithMiniMax(textForTTS, resolvedSettings, config, new AbortController(), true);

  // 存入临时缓存（缓存键与播放/预加载同一套规则，保证能命中）
  const cacheKey = makeVoiceCacheKey(config.model, textForTTS, resolvedVoice);
  tempVoiceCache.set(cacheKey, audioBlob);

  return audioBlob;
}

/**
 * 保存临时语音到持久化缓存（覆盖旧缓存）
 * @param text 文本
 * @param voice 音色（voice_id）
 * @param model 模型（用于生成缓存键，默认 MiniMax 默认模型）
 */
export async function saveTempVoice(text: string, voice: string, model: string = MINIMAX_DEFAULT_MODEL): Promise<void> {
  // 清理文本
  const cleanText = cleanTextForTTS(text);

  const resolvedVoice = await resolveVoiceConfig(voice);
  const cacheKey = makeVoiceCacheKey(model, cleanText, resolvedVoice);

  // 从临时缓存获取
  const audioBlob = tempVoiceCache.get(cacheKey);
  if (!audioBlob) {
    console.warn('[voiceService] 临时缓存中没有找到语音，无法保存');
    return;
  }

  // 写入内存缓存和 IndexedDB（覆盖旧数据）
  cacheMemoryBlob(cacheKey, audioBlob);
  await putVoiceAudio(cacheKey, audioBlob);

  // 清除临时缓存
  tempVoiceCache.delete(cacheKey);
}

/**
 * 取消临时语音（清除临时缓存）
 * @param text 文本
 * @param voice 音色（voice_id）
 * @param model 模型（用于生成缓存键，默认 MiniMax 默认模型）
 */
export async function cancelTempVoice(text: string, voice: string, model: string = MINIMAX_DEFAULT_MODEL): Promise<void> {
  const cleanText = cleanTextForTTS(text);

  const resolvedVoice = await resolveVoiceConfig(voice);
  const cacheKey = makeVoiceCacheKey(model, cleanText, resolvedVoice);

  tempVoiceCache.delete(cacheKey);
}

/**
 * 手动播放语音（优先播放临时缓存，其次持久化缓存）
 * @param text 文本
 * @param voiceSettings 角色语音设置
 * @param config 全局语音配置
 * @param globalVolume 全局音量
 */
export async function manualPlayVoice(
  text: string,
  voiceSettings: CharacterVoiceSettings,
  config: VoiceConfig,
  globalVolume: number = 1.0,
): Promise<void> {
  // 停止之前的播放并生成新的 playId
  stopCurrentVoice();
  currentPlayId++;
  const thisPlayId = currentPlayId;

  // 清理文本
  const cleanText = cleanTextForTTS(text);

  if (!cleanText) {
    console.warn('[voiceService] 清理后文本为空，跳过播放');
    return;
  }

  const resolvedVoice = await resolveVoiceConfig(voiceSettings.voice);
  const cacheKey = makeVoiceCacheKey(config.model, cleanText, resolvedVoice);

  // 检查是否被取消
  if (thisPlayId !== currentPlayId) {
    return;
  }

  // 1. 优先从临时缓存获取（roll 的语音）
  let audioBlob = tempVoiceCache.get(cacheKey);

  // 2. 其次从内存缓存获取
  if (!audioBlob) {
    audioBlob = memoryCache.get(cacheKey);
  }

  // 3. 最后从 IndexedDB 获取
  if (!audioBlob) {
    const cachedBlob = await getVoiceAudio(cacheKey);
    if (cachedBlob) {
      audioBlob = cachedBlob;
      cacheMemoryBlob(cacheKey, cachedBlob);
    }
  }

  // 再次检查是否被取消
  if (thisPlayId !== currentPlayId) {
    return;
  }

  // 4. 如果都没有，提示用户
  if (!audioBlob) {
    console.warn('[voiceService] 未找到缓存的语音');
    return;
  }

  // 播放
  const finalVolume = voiceSettings.volume * globalVolume;
  await playVoiceAudio(audioBlob, finalVolume, thisPlayId);
}
