/**
 * Vibe 编码存储（酒馆服务器）
 *
 * Vibe 编码是大段 base64，不适合塞进全局变量（会撑大 settings.json），因此放到酒馆服务器的
 * user/files 下：同一酒馆实例的所有端都能读取，实现 Vibe 方案的双端同步。
 * 文件名由 encodingKey 派生（只保留安全字符），内容为 `{ v: 1, encoding }` 的 JSON。
 */

import { deleteTextFile, readTextFile, uploadTextFile } from './serverStore';

const FILE_PREFIX = 'novelui_vibe_';

/** encodingKey → 服务器文件名（字符集必须满足酒馆校验 `[a-zA-Z0-9_\-.]+`） */
function fileNameFor(key: string): string {
  const safe = key.replace(/[^a-zA-Z0-9_-]/g, '');
  return `${FILE_PREFIX}${safe || 'unknown'}.json`;
}

/** 存入 Vibe 编码 */
export async function putVibeEncoding(key: string, encoding: string): Promise<void> {
  await uploadTextFile(fileNameFor(key), JSON.stringify({ v: 1, encoding }));
}

/** 批量读取 Vibe 编码；不存在或非法的 key 不会出现在返回的映射里 */
export async function getVibeEncodings(keys: string[]): Promise<Map<string, string>> {
  const result = new Map<string, string>();
  if (keys.length === 0) return result;
  await Promise.all(
    keys.map(async key => {
      try {
        const text = await readTextFile(fileNameFor(key));
        if (!text) return;
        const parsed = JSON.parse(text) as { encoding?: unknown };
        if (typeof parsed?.encoding === 'string' && parsed.encoding) {
          result.set(key, parsed.encoding);
        }
      } catch (e) {
        console.warn('[vibeEncodingStore] 读取 Vibe 编码失败:', key, e);
      }
    }),
  );
  return result;
}

/** 删除 Vibe 编码（不存在时静默） */
export async function deleteVibeEncoding(key: string): Promise<void> {
  try {
    await deleteTextFile(fileNameFor(key));
  } catch (e) {
    console.warn('[vibeEncodingStore] 删除 Vibe 编码失败:', key, e);
  }
}
